// Returns { connected, account? } for a single service. Reads legacy fields
// (user.github_pat, user.outgoing_webhooks.{slack,discord}) so MIGRATING
// users see their existing setup reflected as ✓ Connected without re-entry.
// Google Workspace bundle — these 6 service IDs all share one OAuth flow.
// When user.integrations.google is populated, all 6 are marked connected.
const GOOGLE_BUNDLE_IDS = new Set(['gmail','google_calendar','google_drive','ga4','youtube','search_console']);

function _getIntegrationStatus(user, id){
  if(!user) return { connected: false };
  if(id === 'github'){
    if(user.github_pat) return { connected: true, account: user.github_login || '' };
    return { connected: false };
  }
  // Google bundle: any of the 6 service IDs reads from user.integrations.google.
  // Also surface backward-compat with the older google_oauth field (set when
  // user paired Sheets via the legacy /api/google/sheets flow).
  if(GOOGLE_BUNDLE_IDS.has(id)){
    const g = user.integrations && user.integrations.google;
    if(g && g.access_token){
      return { connected: true, account: g.email || '' };
    }
    // Legacy: Sheets-only token gives a partial connection — flag Calendar
    // and Drive (Sheets is covered by sheets scope) as connected.
    if(user.google_oauth && user.google_oauth.access_token){
      // The legacy scope was sheets + calendar. We don't know if it included
      // gmail/drive/ga4/yt/sc, so only mark gmail-adjacent ones if scopes match.
      const scope = String(user.google_oauth.scope || '');
      if((id === 'google_calendar') && scope.includes('calendar')) return { connected: true, account: g && g.email || '' };
      if((id === 'google_drive') && scope.includes('drive')) return { connected: true };
    }
    return { connected: false };
  }
  if(id === 'slack'){
    // New multi-webhook shape OR legacy single URL
    const sl = user.integrations && user.integrations.slack;
    const list = (sl && Array.isArray(sl.webhooks)) ? sl.webhooks : [];
    const legacy = user.outgoing_webhooks && user.outgoing_webhooks.slack ? 1 : 0;
    const total = list.length + legacy;
    if(total > 0) return { connected: true, count: total };
    return { connected: false };
  }
  if(id === 'wordpress'){
    const wp = user.integrations && user.integrations.wordpress;
    const sites = (wp && Array.isArray(wp.sites)) ? wp.sites : [];
    // Legacy single-site shape
    const legacy = wp && wp.siteUrl ? 1 : 0;
    const total = sites.length + legacy;
    if(total > 0) return { connected: true, count: total };
    return { connected: false };
  }
  if(id === 'discord' && user.outgoing_webhooks && user.outgoing_webhooks.discord){
    return { connected: true };
  }
  // X (Twitter): connected when OAuth flow completed
  if(id === 'twitter'){
    const t = user.integrations && user.integrations.twitter;
    if(t && t.access_token){
      return { connected: true, account: t.username || '' };
    }
    return { connected: false };
  }
  // Zapier: multi-webhook — connected if at least 1 Zap registered. Also
  // surface the count so the catalog UI can show "3 Zaps connected".
  if(id === 'zapier'){
    const z = user.integrations && user.integrations.zapier;
    if(!z) return { connected: false };
    const hooks = Array.isArray(z.webhooks) ? z.webhooks : [];
    // Backward compat: legacy single-URL shape from earlier release.
    const legacyUrl = !hooks.length && z.webhookUrl ? 1 : 0;
    const total = hooks.length + legacyUrl;
    if(total > 0) return { connected: true, count: total };
    return { connected: false };
  }
  const v = user.integrations && user.integrations[id];
  if(v && (v.connected_at || v.apiKey || v.token || v.webhookUrl || v.botToken || v.secretKey || v.accessToken || v.appPassword || v.pat)){
    return { connected: true, connected_at: v.connected_at || null };
  }
  return { connected: false };
}

