// USD金額をセント（Stripe用）に変換
function usdToCents(usd){ return Math.round(usd*100); }

// ── RATE LIMITER ──────────────────────────────────────────────
const RL=new Map();
function rateLimit(ip,max=100,win=60000){
  const now=Date.now(),r=RL.get(ip)||{n:0,reset:now+win};
  if(now>r.reset){r.n=0;r.reset=now+win;}
  r.n++;RL.set(ip,r);return r.n<=max;
}
setInterval(()=>{const now=Date.now();for(const[k,v]of RL)if(now>v.reset+60000)RL.delete(k);},120000);

// ── LOCAL DB ──────────────────────────────────────────────────
const DB_PATH=process.env.LDB_PATH||path.join(__dirname,'db.json');
const LDB=(()=>{
  let d={users:[]};
  if(fs.existsSync(DB_PATH)){try{d=JSON.parse(fs.readFileSync(DB_PATH,'utf8'));}catch{}}
  const save=()=>fs.writeFileSync(DB_PATH,JSON.stringify(d,null,2));
  return{
    find:fn=>d.users.find(fn),
    all:()=>d.users.slice(),
    add(u){d.users.push(u);save();},
    upd(u){const i=d.users.findIndex(x=>x.id===u.id);if(i>=0){d.users[i]=u;save();}},
    del(id){const i=d.users.findIndex(x=>x.id===id);if(i>=0){d.users.splice(i,1);save();}},
  };
})();

// ── SUPABASE ──────────────────────────────────────────────────
// Bumped timeout from 8s → 20s. Reasoning:
//   ・write paths can carry a 500KB+ artifacts jsonb row
//   ・Render → Supabase across regions sometimes spikes to 5-10s
//   ・8s was hitting too aggressively under normal load
// _sbReqOnce is the raw single-attempt; sbReq retries once on timeout/network
// error with a fresh attempt, so transient hiccups don't break chat turns.
function _sbReqOnce(method,table,qs='',body=null,timeoutMs=20000){
  return new Promise((res,rej)=>{
    const u=new url.URL(`${SUPA_URL}/rest/v1/${table}${qs}`);
    const pay=body?JSON.stringify(body):null;
    const headers={'apikey':SUPA_KEY,'Authorization':`Bearer ${SUPA_KEY}`,
      'Content-Type':'application/json','Prefer':'return=representation',
      ...(pay?{'Content-Length':Buffer.byteLength(pay)}:{})};
    const req=https.request({
      hostname:u.hostname,path:u.pathname+u.search,method,headers,timeout:timeoutMs
    },r=>{
      // CRITICAL: setEncoding('utf8') so Node buffers incomplete multi-byte
      // sequences across data chunks. Without it, "d += chunk" can split a
      // 3-byte Japanese char between two chunks → 文字化け in agent names,
      // chat history, etc. Same fix as httpsReq above.
      r.setEncoding('utf8');
      let d='';
      r.on('data',c=>d+=c);
      r.on('end',()=>{try{res({s:r.statusCode,d:JSON.parse(d||'[]')});}catch{res({s:r.statusCode,d});}});
    });
    req.on('error',e=>{rej(e);});
    req.on('timeout',()=>{req.destroy();rej(new Error('Supabase timeout'));});
    if(pay)req.write(pay);
    req.end();
  });
}
async function sbReq(method,table,qs='',body=null){
  // 1st attempt with default 20s budget.
  try { return await _sbReqOnce(method,table,qs,body,20000); }
  catch(e){
    const isTimeout = /timeout|ECONNRESET|ETIMEDOUT|EAI_AGAIN|ECONNREFUSED/i.test(String(e && e.message || ''));
    if(!isTimeout) throw e;
    console.warn('[sbReq] retry after timeout:', method, table, qs.slice(0,60));
    // One retry with a generous 25s budget. If this also fails, surface a
    // user-friendly error message via _supaTimeoutErr so the UI shows
    // something actionable instead of "Supabase timeout".
    try { return await _sbReqOnce(method,table,qs,body,25000); }
    catch(e2){
      console.error('[sbReq] FAILED both attempts:', method, table, e2.message);
      throw new Error('データベース混雑のため一時的に保存できませんでした。30 秒待って再試行してください');
    }
  }
}

// All `users` columns EXCEPT the heavy `artifacts` jsonb. Table-scan queries
// (admin stats, marketplace, creator pages) never read artifact HTML, so
// excluding the single heaviest column cuts Supabase egress hard. DB.findBy
// keeps select=* because /api/me needs artifacts. NOTE: if a new column is
// added to the schema, append it here so table-scan endpoints still see it.
const USER_COLS_LEAN = 'id,name,email,password,plan,balance_jpy,agents,usage_count,billing_history,stripe_customer_id,google_id,verified,verify_token,reset_token,reset_expiry,deleted,created_at,balance_jpy_pending,balance_jpy_available,revenue_history,payout_history,is_verified,favorites,stripe_connect_id,stripe_connect_payouts_enabled,stripe_connect_charges_enabled,stripe_connect_details_submitted,subscription_id,subscription_status,is_admin,google_oauth,extension_device_id,extension_device_token,extension_device_meta,mobile_devices,group_memberships,outgoing_webhooks,handle,is_founder,founder_seat_no,founder_granted_at,business_trial_until,referral_code,referred_by,referral_stats,login_history,role,memories,chat_pinned,reactions,integrations,github_pat,github_login,notes,reminders,purchases,mcp_servers,onboarded_at,last_nudge_global_at,last_stripe_event_at,last_weekly_digest_at,marketing_attribution,lang,google_sheets_connected,mention_email_pref';

// ── DB ABSTRACTION ────────────────────────────────────────────
// 注意: コードと Supabase スキーマは共に snake_case を使用。case 変換は不要。
const DB={
  async findBy(field,val){
    if(!USE_SUPA)return LDB.find(u=>u[field]===val)||null;
    const r=await sbReq('GET','users','?select=*&'+field+'=eq.'+encodeURIComponent(val)+'&limit=1');
    if(!r.d||!r.d[0])return null;
    return r.d[0];
  },
  async create(user){
    if(!USE_SUPA){LDB.add(user);return user;}
    // Auto-retry: drop unknown columns (e.g., new fields added before migration)
    // so signup never silently fails if a migration is pending. Same defensive
    // pattern as DB.save.
    const payload = {...user};
    for(let attempt=0; attempt<12; attempt++){
      const r = await sbReq('POST','users','',payload);
      if(r.s < 400){
        const arr = Array.isArray(r.d) ? r.d : [r.d];
        return arr[0] || user;
      }
      const msg = (r.d && (r.d.message || r.d.hint)) || '';
      const m = msg.match(/Could not find the '([\w_]+)' column/);
      if(m && payload[m[1]] !== undefined){
        console.warn('[DB.create] dropping unknown column "'+m[1]+'" — run docs/SUPABASE_MIGRATION.sql to add it');
        delete payload[m[1]];
        continue;
      }
      console.error('[DB.create] Supabase rejected (HTTP '+r.s+'):', JSON.stringify(r.d).slice(0,400));
      // Don't return the in-memory user (that masked the bug). Throw so the
      // signup endpoint surfaces a 500 instead of pretending success.
      throw new Error('Supabase create failed: ' + (msg || 'HTTP '+r.s));
    }
    throw new Error('Supabase create failed after column-drop retries');
  },
  async save(user){
    // ── JSONB row diet — safety net for old / accumulated state ──
    // Even if create/edit paths cap properly going forward, users may already
    // have multi-MB rows from before. Run every save through a compactor so
    // the row shrinks on next write. Same 3 rules as the create path:
    //   (1) max 30 artifacts (oldest dropped)
    //   (2) max 1 version snapshot per artifact
    //   (3) artifacts not touched in 7+ days → html stripped (keep metadata)
    // Mutation is on the in-memory user too, not just the payload — so
    // subsequent calls in the same request see the diet'd version.
    const _compactArtifacts = (u) => {
      if(!u || !Array.isArray(u.artifacts) || u.artifacts.length === 0) return;
      if(u.artifacts.length > 30){
        u.artifacts.splice(0, u.artifacts.length - 30);
      }
      const STALE_MS = 7 * 24 * 60 * 60 * 1000;
      const now = Date.now();
      for(const a of u.artifacts){
        if(!a) continue;
        if(Array.isArray(a.versions) && a.versions.length > 1){
          a.versions = a.versions.slice(-1);
        }
        const ts = Date.parse(a.updated_at || a.created_at || '') || 0;
        if(ts > 0 && now - ts > STALE_MS && typeof a.html === 'string' && a.html.length > 500){
          a.html = null;
          a.html_stripped = true;
        }
      }
    };
    _compactArtifacts(user);
    // ── Sanitize: never persist streaming:true on history entries ──
    // An interrupted SSE leaves a stale "🍑 生成中…" bubble in the in-memory
    // agent.history. Without this sanitize step, the chat handler's append
    // pattern (history = [...existing, new]) preserves the bad entry on
    // every subsequent save → the stuck bubble lives forever in the DB.
    // Run on BOTH in-memory user (so subsequent reads are clean) and the
    // PATCH payload (so the DB is definitively cleaned).
    const _sanitizeAgentHistories = (u) => {
      if(!u || !Array.isArray(u.agents)) return;
      for(const ag of u.agents){
        if(!ag || !Array.isArray(ag.history)) continue;
        for(const m of ag.history){
          if(m && m.streaming){
            m.streaming = false;
            m.truncated = true;
            if(!m.content || !String(m.content).trim()){
              m.content = '(応答が途中で切れました)';
              m.was_stopped = true;
            }
          }
        }
      }
    };
    _sanitizeAgentHistories(user);
    if(!USE_SUPA){LDB.upd(user);return;}
    const payload = {...user};
    delete payload.id; // never update primary key
    _compactArtifacts(payload);  // double-apply on payload for safety
    _sanitizeAgentHistories(payload);
    for(let attempt=0; attempt<12; attempt++){
      // select=id → the PATCH echoes back only [{id}] instead of the entire
      // (multi-KB, artifacts+history-laden) row. Halves egress on every save;
      // the 0-rows RLS check below still works on the trimmed array.
      const r = await sbReq('PATCH','users','?id=eq.'+user.id+'&select=id',payload);
      if(r.s<400){
        // Verify the PATCH actually hit a row. With Prefer: return=representation,
        // r.d should be an array of updated rows. Empty array == nothing matched.
        if(Array.isArray(r.d) && r.d.length===0){
          console.error('[DB.save] PATCH returned 0 rows for id='+user.id+' — RLS policy or wrong key? plan saved=NO');
          throw new Error('Supabase: 0 rows updated (RLS policy blocking, or service key wrong)');
        }
        // Useful diagnostic: log when plan changed
        if(payload.plan){
          console.log('[DB.save] saved id='+user.id+' plan='+payload.plan+' rows='+(Array.isArray(r.d)?r.d.length:'?'));
        }
        return;
      }
      const msg = (r.d && (r.d.message || r.d.hint)) || '';
      const m = msg.match(/Could not find the '([\w_]+)' column/);
      if(m && payload[m[1]] !== undefined){
        console.warn('[DB.save] dropping unknown column "'+m[1]+'"');
        delete payload[m[1]];
        continue;
      }
      console.error('[DB.save] Supabase rejected (HTTP '+r.s+'):', JSON.stringify(r.d).slice(0,400));
      throw new Error(msg || 'Supabase save failed (HTTP '+r.s+')');
    }
    throw new Error('Supabase save failed after retries');
  },
  async remove(id){
    if(!USE_SUPA){LDB.data=(LDB.data||[]).filter(u=>u.id!==id);return true;}
    const r=await sbReq('DELETE','users','?id=eq.'+id);
    return r.s<300;
  },
  // Founder 100: count how many seats are already allocated.
  async countFounders(){
    if(!USE_SUPA){
      return LDB.all().filter(u => u.is_founder).length;
    }
    const r = await sbReq('GET','users','?select=id&is_founder=eq.true&limit=200');
    return Array.isArray(r.d) ? r.d.length : 0;
  },
  // For marketing daily-report aggregation: pull users created in a UTC window.
  async findAllCreatedBetween(startIso, endIso){
    if(!USE_SUPA){
      return LDB.all().filter(u => u.created_at >= startIso && u.created_at < endIso);
    }
    const qs = '?select=id,email,marketing_attribution,created_at'
      + '&created_at=gte.' + encodeURIComponent(startIso)
      + '&created_at=lt.'  + encodeURIComponent(endIso)
      + '&limit=10000';
    const r = await sbReq('GET','users',qs);
    return Array.isArray(r.d) ? r.d : [];
  },
};

// ── JWT ───────────────────────────────────────────────────────
const JWT={
  sign(p,exp=86400000*30){
    const h=Buffer.from(JSON.stringify({alg:'HS256',typ:'JWT'})).toString('base64url');
    const b=Buffer.from(JSON.stringify({...p,exp:Date.now()+exp})).toString('base64url');
    const s=crypto.createHmac('sha256',JWT_SECRET).update(`${h}.${b}`).digest('base64url');
    return`${h}.${b}.${s}`;
  },
  verify(t){
    try{
      const[h,b,s]=(t||'').split('.');
      const e=crypto.createHmac('sha256',JWT_SECRET).update(`${h}.${b}`).digest('base64url');
      if(s!==e)return null;
      const p=JSON.parse(Buffer.from(b,'base64url').toString());
      if(p.exp&&Date.now()>p.exp)return null;return p;
    }catch{return null;}
  },
};

// ── PASSWORD ──────────────────────────────────────────────────
const PW={
  hash(pw){const s=crypto.randomBytes(16).toString('hex');return s+':'+crypto.pbkdf2Sync(pw,s,100000,64,'sha512').toString('hex');},
  check(pw,stored){
    if(!stored)return false;
    const[s,h]=stored.split(':');
    try{return crypto.timingSafeEqual(Buffer.from(h,'hex'),crypto.pbkdf2Sync(pw,s,100000,64,'sha512'));}
    catch{return false;}
  },
};

// ── HTTP HELPERS ──────────────────────────────────────────────
const SEC={'X-Content-Type-Options':'nosniff','X-Frame-Options':'DENY','Referrer-Policy':'strict-origin-when-cross-origin'};
function jres(res,status,data){
  const body=JSON.stringify(data);
  res.writeHead(status,{'Content-Type':'application/json','Content-Length':Buffer.byteLength(body),'Access-Control-Allow-Origin':APP_URL,...SEC});
  res.end(body);
}
// Max body size: 50 MB. PDF / image attachments are sent base64 (~1.37x
// inflation) so a 32 MB PDF (Anthropic's per-request cap) fits comfortably
// here with headroom for JSON wrapping. Frontend caps individual attachments
// at 32 MB so this is the right ceiling.
function readBody(req,max=50*1024*1024){
  return new Promise((resolve,reject)=>{
    let b='',sz=0,settled=false;
    req.on('data',c=>{
      if(settled) return;
      sz+=c.length;
      if(sz>max){
        settled=true;
        try{ req.destroy(); }catch(e){}
        const err = new Error('Body too large');
        err.statusCode = 413;
        reject(err);
        return;
      }
      b+=c;
    });
    req.on('end',()=>{
      if(settled) return;
      settled=true;
      try{ resolve(JSON.parse(b||'{}')); }catch{ resolve({}); }
    });
    req.on('error',(e)=>{
      if(settled) return;
      settled=true; reject(e);
    });
  });
}
function readRaw(req){return new Promise((resolve,reject)=>{const c=[];req.on('data',d=>c.push(d));req.on('end',()=>resolve(Buffer.concat(c)));req.on('error',reject);});}
function getAuth(req){return JWT.verify((req.headers['authorization']||'').replace('Bearer ',''));}
function getIP(req){return(req.headers['x-forwarded-for']||req.socket.remoteAddress||'').split(',')[0].trim();}
// ── Agent progression (level / XP) — Phase 1 of the agent state model ──
// XP accrues from real work: each completed chat turn + each tool run.
// `level` is always DERIVED from xp (xp is the single source of truth).
// Agent fields live inside the users.agents jsonb, so no schema migration.
const XP_PER_TURN = 12;
const XP_PER_TOOL = 6;
function _xpForLevel(lv){              // cumulative XP required to REACH level lv
  if(lv <= 1) return 0;
  return Math.round(30 * Math.pow(lv - 1, 1.6));
}
function _levelForXp(xp){
  xp = Math.max(0, xp || 0);
  let lv = 1;
  while(lv < 999 && _xpForLevel(lv + 1) <= xp) lv++;
  return lv;
}
// Count completed assistant turns + tool runs across an agent's full history
// (live + archived) — used to backfill agents that predate the XP system.
function _scanHistoryXp(agent){
  let turns = 0, tools = 0, errors = 0;
  for(const arr of [agent && agent.history, agent && agent.history_archive]){
    if(!Array.isArray(arr)) continue;
    for(const m of arr){
      if(m && m.role === 'assistant' && !m._summary){
        turns++;
        if(m.is_error) errors++;
        if(Array.isArray(m.tool_log)) tools += m.tool_log.length;
      }
    }
  }
  return { turns, tools, errors };
}
// Read-only progress snapshot for the client (level / xp / progress bar).
function _agentProgress(agent){
  let xp;
  if(agent && typeof agent.xp === 'number'){
    xp = Math.max(0, agent.xp);
  } else {
    const s = _scanHistoryXp(agent);   // derive for legacy agents
    xp = s.turns * XP_PER_TURN + s.tools * XP_PER_TOOL;
  }
  const level = _levelForXp(xp);
  const cur = _xpForLevel(level), next = _xpForLevel(level + 1);
  const span = Math.max(1, next - cur);
  const scan = (agent && typeof agent.turn_count === 'number') ? null : _scanHistoryXp(agent);
  return {
    xp, level,
    output_count: (agent && typeof agent.turn_count === 'number') ? agent.turn_count : scan.turns,
    tool_count:   (agent && typeof agent.tool_count === 'number') ? agent.tool_count : scan.tools,
    xp_into_level: xp - cur,
    xp_to_next:    next - cur,
    progress_pct:  Math.min(100, Math.max(0, Math.round(((xp - cur) / span) * 100))),
  };
}
// Award XP for a just-completed turn. Call AFTER the assistant message is
// pushed to agent.history. Backfills xp from history on first use so legacy
// agents keep their accumulated progress instead of resetting to Lv.1.
function _awardAgentXp(agent){
  if(!agent) return;
  if(typeof agent.xp !== 'number'){
    // First award for a legacy agent — seed from full history, which already
    // includes the turn that just completed, so don't double-count it.
    const s = _scanHistoryXp(agent);
    agent.turn_count = s.turns;
    agent.tool_count = s.tools;
    agent.error_count = s.errors;
    agent.xp = s.turns * XP_PER_TURN + s.tools * XP_PER_TOOL;
    agent.last_active_at = new Date().toISOString();
    return;
  }
  // Tools used / error state of the just-completed turn = last assistant msg.
  let tools = 0, wasError = false;
  const h = agent.history || [];
  for(let i = h.length - 1; i >= 0; i--){
    if(h[i] && h[i].role === 'assistant'){
      tools = Array.isArray(h[i].tool_log) ? h[i].tool_log.length : 0;
      wasError = !!h[i].is_error;
      break;
    }
  }
  agent.turn_count = (agent.turn_count || 0) + 1;
  agent.tool_count = (agent.tool_count || 0) + tools;
  agent.error_count = (agent.error_count || 0) + (wasError ? 1 : 0);
  agent.xp = (agent.xp || 0) + XP_PER_TURN + tools * XP_PER_TOOL;
  agent.last_active_at = new Date().toISOString();
}

// ── Agent trust (Phase 2) — derived reliability score, display-only in v1 ──
// Distinct from level (level = experience/volume). Trust = "how much you can
// rely on it": sustained work + tenure − error rate. Fully derived (no stored
// field). The autonomy-unlock role comes with the delegation system (v2).
function _agentTrust(agent){
  const scan = (agent && typeof agent.turn_count === 'number') ? null : _scanHistoryXp(agent);
  const turns = scan ? scan.turns : agent.turn_count;
  // An agent that has done no work is unproven — lowest trust, full stop.
  if(!turns || turns < 1) return { score: 0, level: 1 };
  const errors = (agent && typeof agent.error_count === 'number')
    ? agent.error_count : (scan ? scan.errors : _scanHistoryXp(agent).errors);
  // Work done is the main driver (caps at 85).
  const workPts = Math.min(85, turns * 1.1);
  // Tenure — a small bonus for an agent that has been around (caps at 15).
  let tenurePts = 0;
  const created = agent && agent.created_at && Date.parse(agent.created_at);
  if(created && !isNaN(created)){
    tenurePts = Math.min(15, Math.max(0, (Date.now() - created) / 86400000) * 0.5);
  }
  // Errors scale the whole score down.
  const errRate = Math.min(1, errors / turns);
  const score = Math.round(Math.min(100, Math.max(0, (workPts + tenurePts) * (1 - errRate * 0.7))));
  const level = Math.max(1, Math.min(5, 1 + Math.floor(score / 20)));
  return { score, level };
}

// ── Agent outcomes (Phase 4) — derived result summary, display-only ──
// v1 reports what we can know automatically: turn completion vs failure
// (a turn "failed" if the assistant errored or any tool in it returned
// ok:false). Richer real-world outcomes (返信獲得/アポ獲得) need user
// marking or CRM integration → deferred to v2.
function _agentOutcomes(agent){
  const scan = (agent && typeof agent.turn_count === 'number') ? null : _scanHistoryXp(agent);
  const total  = scan ? scan.turns  : agent.turn_count;
  const failed = (agent && typeof agent.error_count === 'number')
    ? agent.error_count : (scan ? scan.errors : _scanHistoryXp(agent).errors);
  const completed = Math.max(0, total - failed);
  const success_rate = total > 0 ? Math.round((completed / total) * 100) : 0;
  // Recent outputs for the card list — most recent assistant turns first.
  const recent = [];
  const h = Array.isArray(agent && agent.history) ? agent.history : [];
  for(let i = h.length - 1; i >= 0 && recent.length < 6; i--){
    const m = h[i];
    if(!m || m.role !== 'assistant' || m._summary) continue;
    const toolFail = Array.isArray(m.tool_log) && m.tool_log.some(t => t && t.ok === false);
    recent.push({
      title: String(m.content || '').replace(/[#*`>_\n\r]+/g, ' ').trim().slice(0, 64) || '(出力)',
      time: m.time || '',
      status: (m.is_error || toolFail) ? 'failed' : 'done',
    });
  }
  return { total, completed, failed, success_rate, recent };
}

// ── Agent digest (Phase 5) — recent activity, derived from billing_history ──
// billing_history carries a timestamped (ISO `date`) record per turn, so we
// can honestly report recent-activity windows. A richer per-tool breakdown
// ("emails sent / research done") needs a timestamped action log → v2.
function _agentDigest(agent, user){
  const bh = Array.isArray(user && user.billing_history) ? user.billing_history : [];
  const now = Date.now(), DAY = 86400000;
  const aid = agent && agent.id;
  let t24 = 0, t7d = 0;
  let lastAt = (agent && agent.last_active_at) || null;
  for(const e of bh){
    if(!e || e.agentId !== aid || e.type !== 'usage') continue;
    const d = e.date && Date.parse(e.date);
    if(!d || isNaN(d)) continue;
    if(now - d <= DAY)      t24++;
    if(now - d <= 7 * DAY)  t7d++;
    if(!lastAt || d > Date.parse(lastAt)) lastAt = e.date;
  }
  return { turns_24h: t24, turns_7d: t7d, last_active_at: lastAt };
}

function safe(u){
  const{password:_,verify_token:__,reset_token:___,reset_expiry:____,
        google_oauth:gOAuth,
        extension_device_token:extTok,
        github_pat:ghPat,
        ...s}=u;
  // Expose only the *connection state* — never the secret tokens themselves.
  s.google_sheets_connected = !!(gOAuth && gOAuth.refresh_token);
  s.google_sheets_email = (gOAuth && gOAuth.email) || null;
  s.extension_paired = !!extTok;
  s.extension_connected = !!(extTok && _extConnections.has(extTok));
  s.github_connected = !!ghPat;
  // Plan v2 surface (frontend uses this to render correct credit amount and
  // gate Team / agent-cap UIs without doing date math itself).
  s.plan_v2_grandfathered = _isGrandfathered(u);
  // Scrub stale streaming flags in every agent's history before sending.
  // A streaming:true entry that was persisted means the previous SSE session
  // was interrupted (Render deploy, browser close, network blip). Without
  // this, the bubble renders as "🍑 生成中…" forever after reload.
  if(Array.isArray(s.agents)){
    for(const ag of s.agents){
      if(!ag) continue;
      // Attach computed agent-state snapshots so the client doesn't
      // re-implement the logic (Phase 1/2/4 of the agent state model).
      ag.progress = _agentProgress(ag);
      ag.trust = _agentTrust(ag);
      ag.outcomes = _agentOutcomes(ag);
      ag.digest = _agentDigest(ag, u);
      if(!Array.isArray(ag.history)) continue;
      for(const m of ag.history){
        if(m && m.streaming){
          m.streaming = false;
          m.truncated = true;
          if(!m.content || !String(m.content).trim()){
            m.content = '(応答が途中で切れました)';
            m.was_stopped = true;
          }
        }
      }
    }
  }
  // Strip the heavy `html` body from artifacts in the chat-load payload — the
  // client renders artifacts by URL, never from this field. Each artifact's
  // html can be 100s of KB; with up to 100 artifacts that bloated every
  // /api/me. Full html stays in the DB (edit_artifact / static serving use it).
  if(Array.isArray(s.artifacts)){
    s.artifacts = s.artifacts.map(a => {
      if(!a || typeof a !== 'object') return a;
      const { html:_html, versions, ...rest } = a;
      // Version metadata only — drop the heavy html snapshots from the payload.
      if(Array.isArray(versions)) rest.versions = versions.map(v => ({ at: v && v.at, op: v && v.op }));
      return rest;
    });
  }
  return s;
}
// Free-tier starting credit (JPY). Tunable via env so we can throttle burn
// from Render without a deploy. ¥500 ≒ a few chats + 1〜2 artifacts — enough
// to hit the "aha", small enough that 10-account farming isn't profitable.
const FREE_INITIAL_CREDIT_JPY = parseInt(process.env.FREE_INITIAL_CREDIT_JPY||'500',10) || 500;

// ── TEAM PRESETS — Web サイト集客 AI チームの 6 vertical 定義 ──────────
// LP で打ち出してる 5 vertical (SaaS / EC / 店舗 / ブログ / ポートフォリオ)
// + fallback の汎用チーム。 URL から Haiku が site_vertical を判定 → ここから
// 該当 preset を引いて agent (= site team) を編成する。
//
// 構造:
//   - label / icon: UI 表示用
//   - description: ユーザーに見せる「このチームは何をやるか」の 1 文
//   - members[]: 5 役。name / role / focus は チームメンバー UI 表示用
//   - system_prompt: 編成された agent.persona に注入される (= AI の behavior 定義)
//   - initial_artifact_prompts[]: onboarding 直後に並列生成する artifact のプロンプト
//   - detection_keywords[]: Haiku の参考材料 (hints) — 厳密には使わず prompt 注入のみ
// ── 組織テンプレ helper: 部門→チーム→メンバー の 3 階層を組み立てる ──
// 各 vertical の .org は { departments: [...] } の形。department は icon / color /
// teams[] を持つ。各 team は members[] を持つ。
// member は { id, name, role, focus } — role は AI agent の専門性スラグ。
function _orgD(id, name, icon, color, teams){
  return { id, name, icon, color, teams };
}
function _orgT(id, name, members){
  return { id, name, members };
}
function _orgM(id, name, role, focus){
  return { id, name, role, focus };
}

