// ── PUSH NOTIFICATIONS (FCM legacy + APNs proxied via FCM) ───
// Send a notification to one device token. Gated behind FCM_SERVER_KEY:
// when not configured (dev / before Firebase setup), logs and returns OK.
// Production: set FCM_SERVER_KEY in Render env to the legacy server key
// from Firebase Console → Project Settings → Cloud Messaging.
async function sendPushFCM(token, payload){
  if(!process.env.FCM_SERVER_KEY){
    if(process.env.PUSH_DEBUG === '1'){
      console.log('[push] would send:', JSON.stringify({token: (token||'').slice(0,16)+'…', payload}).slice(0, 300));
    }
    return { ok: false, reason: 'fcm_not_configured' };
  }
  try {
    const body = {
      to: token,
      notification: {
        title: payload.title || 'MY AI Agent',
        body:  payload.body  || '',
        sound: 'default',
        badge: payload.badge || 1,
      },
      data: payload.data || {},
      priority: 'high',
    };
    const r = await httpsReq('POST', 'fcm.googleapis.com', '/fcm/send', {
      'Authorization': 'key=' + process.env.FCM_SERVER_KEY,
      'Content-Type': 'application/json',
    }, body);
    return { ok: r.s < 400, status: r.s };
  } catch(e){
    console.warn('[push] FCM send failed:', e.message);
    return { ok: false, error: e.message };
  }
}

// Notify group members of a new message. Respects per-user notify_pref:
//   'all'      → always send
//   'mentions' → only when @AI / @name was used
//   'mute'     → never send
// Skips the sender's own devices. Fire-and-forget.
async function notifyGroupMembers(host, agent, opts){
  try {
    if(!agent || !agent.is_group || !Array.isArray(agent.members)) return;
    const senderUid   = opts.sender_user_id || '';
    const senderName  = opts.sender_name || 'メンバー';
    const messageText = (opts.text || '').toString().slice(0, 200);
    const isAIReply   = !!opts.is_ai_reply;
    const isMention   = !!opts.is_mention;

    const targets = agent.members.filter(m => {
      if(!m || !m.user_id) return false;
      // Don't notify the sender (unless this is an AI reply — sender wants to know AI replied)
      if(m.user_id === senderUid && !isAIReply) return false;
      const pref = m.notify_pref || 'all';
      if(pref === 'mute') return false;
      if(pref === 'mentions' && !isMention && !isAIReply) return false;
      return true;
    });
    if(!targets.length) return;

    const title = agent.name || 'グループ';
    const body  = isAIReply
      ? (agent.name + ': ' + messageText)
      : (senderName + ': ' + messageText);

    for(const m of targets){
      const member = await DB.findBy('id', m.user_id);
      if(!member) continue;
      const devices = Array.isArray(member.mobile_devices) ? member.mobile_devices : [];
      if(!devices.length) continue;
      const payload = {
        title, body,
        data: {
          type: 'group_message',
          agent_id: agent.id,
          host_id: host.id,
          sender_user_id: senderUid,
          is_ai_reply: isAIReply ? '1' : '0',
        },
      };
      for(const d of devices){
        await sendPushFCM(d.token, payload).catch(()=>{});
      }
    }
  } catch(e){
    console.warn('[push] notifyGroupMembers error:', e.message);
  }
}

// ── @MENTION → EMAIL NOTIFICATION ─────────────────────────────
// When a user @mentions someone by name in a group chat, email that person
// (Slack-style "you were mentioned" notification). Resolves names against
// group.members[], throttles to 1 email per (sender, recipient, group) per
// 5 min, and honors per-user opt-out (user.mention_email_pref === 'off').
const _mentionEmailThrottle = new Map(); // key: senderUid+recipientUid+groupId → ts(ms)
const _MENTION_EMAIL_THROTTLE_MS = 5 * 60 * 1000; // 5 min
async function _notifyMentionsByEmail(host, agent, opts){
  try {
    if(!agent || !agent.is_group || !Array.isArray(agent.members)) return;
    const senderUid  = opts.sender_user_id || '';
    const senderName = opts.sender_name || 'メンバー';
    const text       = String(opts.text || '');
    if(!text || text.length < 1) return;
    // Extract @mentions: whitelist-only chars so trailing punctuation like
    // "@田中、" doesn't get swallowed into the captured name.
    //   - a-zA-Z0-9_       latin alnum + underscore
    //   - 3040-309f         Hiragana
    //   - 30a0-30ff         Katakana
    //   - 4e00-9fff         CJK Unified Ideographs (common kanji)
    //   - ff10-ff19,21-3a,41-5a,61-7a  Fullwidth alnum (rare)
    const MENTION_RE = /(?:^|[\s　])[@＠]([a-zA-Z0-9_぀-ゟ゠-ヿ一-鿿０-９Ａ-Ｚａ-ｚ]{1,24})/g;
    const matches = [];
    let _mm;
    while((_mm = MENTION_RE.exec(text)) !== null){
      const tok = (_mm[1] || '').trim();
      if(tok && !/^(ai|here|all|channel|everyone)$/i.test(tok)) matches.push(tok);
    }
    if(!matches.length) return;
    // Resolve mentions → group members.
    //   1. exact match (case-insensitive, whitespace-normalized) — preferred
    //   2. member name is a 2+ char prefix of the mention   ("@田中太郎" → "田中")
    //   3. mention is a 2+ char prefix of the member name   ("@田" → "田中")
    // Without the 2-char floor, "@k" would match any member starting with "k".
    const _norm = (s) => String(s||'').toLowerCase().replace(/[\s　]+/g,'');
    const seenUids = new Set();
    const targets = [];
    for(const m of matches){
      const mn = _norm(m);
      if(!mn) continue;
      // First pass: exact match
      let hit = agent.members.find(mem => {
        if(!mem || !mem.user_id) return false;
        if(mem.user_id === senderUid) return false;
        if(seenUids.has(mem.user_id)) return false;
        return _norm(mem.name) === mn;
      });
      // Second pass: prefix (with 2-char floor)
      if(!hit){
        hit = agent.members.find(mem => {
          if(!mem || !mem.user_id) return false;
          if(mem.user_id === senderUid) return false;
          if(seenUids.has(mem.user_id)) return false;
          const nm = _norm(mem.name);
          if(!nm) return false;
          if(mn.length >= 2 && nm.startsWith(mn)) return true;
          if(nm.length >= 2 && mn.startsWith(nm)) return true;
          return false;
        });
      }
      if(hit){
        seenUids.add(hit.user_id);
        targets.push(hit);
      }
    }
    if(!targets.length) return;
    const groupId = agent.id;
    // Sanitize for the email subject header — strip CR/LF and other control
    // chars to prevent header injection / API rejection by Resend.
    const _safeForHeader = (s) => String(s || '').replace(/[\u0000-\r\n]+/g, ' ').trim().slice(0, 80);
    const groupName     = _safeForHeader(agent.name || 'グループ');
    const safeSenderName = _safeForHeader(senderName);
    const previewText = text.length > 200 ? text.slice(0, 200) + '…' : text;
    const appUrl = (APP_URL || 'https://myaiagents.agency').replace(/\/$/, '');
    for(const tgt of targets){
      // Throttle: skip if we already emailed this pair recently.
      const key = senderUid + '|' + tgt.user_id + '|' + groupId;
      const last = _mentionEmailThrottle.get(key) || 0;
      if(Date.now() - last < _MENTION_EMAIL_THROTTLE_MS) continue;
      // Fetch recipient (need email + opt-out pref).
      const recipient = await DB.findBy('id', tgt.user_id);
      if(!recipient || !recipient.email) continue;
      // Opt-out: per-user setting, default ON.
      if(recipient.mention_email_pref === 'off') continue;
      const subj = '🔔 ' + senderName + ' さんがあなたをメンションしました — ' + groupName;
      const settingsUrl = appUrl + '/app#settings/notif';
      const chatUrl = appUrl + '/app?agent=' + encodeURIComponent(groupId);
      const html = '<div style="font-family:system-ui,-apple-system,Segoe UI,Hiragino Sans,Noto Sans JP,sans-serif;max-width:560px;margin:0 auto;padding:20px;color:#27272a">'
        + '<div style="font-size:13px;color:#71717a;margin-bottom:6px">🔔 ' + _xmlEscape(groupName) + '</div>'
        + '<div style="font-size:17px;font-weight:800;margin-bottom:14px;color:#18181b">'
        +   _xmlEscape(senderName) + ' さんがあなたをメンションしました'
        + '</div>'
        + '<div style="background:#fff7ed;border:1px solid #fed7aa;border-left:4px solid #fb923c;border-radius:10px;padding:14px 16px;font-size:14px;line-height:1.55;white-space:pre-wrap;margin-bottom:18px;color:#1c1917">'
        +   _xmlEscape(previewText)
        + '</div>'
        + '<a href="' + _xmlEscape(chatUrl) + '" style="display:inline-block;background:#fb923c;color:#fff;text-decoration:none;font-weight:800;padding:11px 22px;border-radius:9px;font-size:13.5px">このメッセージに返信 →</a>'
        + '<div style="margin-top:30px;padding-top:14px;border-top:1px solid #e4e4e7;font-size:11px;color:#a1a1aa;line-height:1.55">'
        +   'このメールは <b>'+ _xmlEscape(groupName) +'</b> グループでメンションされたため送信されました。<br>'
        +   '<a href="' + _xmlEscape(settingsUrl) + '" style="color:#9a3412">メール通知をオフにする</a>'
        + '</div>'
        + '</div>';
      sendEmail(recipient.email, subj, html, { fromName: senderName + ' (MY AI Agent)' })
        .then(() => { _mentionEmailThrottle.set(key, Date.now()); })
        .catch(e => { console.warn('[mention-email] failed:', e.message); });
    }
  } catch(e){
    console.warn('[mention-email] error:', e.message);
  }
}

// Periodic cleanup of stale throttle entries (every 10 min).
setInterval(() => {
  try {
    const cutoff = Date.now() - _MENTION_EMAIL_THROTTLE_MS;
    for(const [k, ts] of _mentionEmailThrottle){
      if(ts < cutoff) _mentionEmailThrottle.delete(k);
    }
  } catch(e){}
}, 10 * 60 * 1000);

// ── EMAIL (Resend) ────────────────────────────────────────────
// fromName: optional human-friendly display name. Defaults to "MY AI Agent"
// for system mails (verify, reset, daily report). The send_email tool passes
// the agent's name so the recipient sees who actually composed the message.
// Strip control + quote chars from the display name — RFC 5322 doesn't like
// them in an unquoted addr-spec.
function _safeFromName(name){
  return String(name || 'MY AI Agent')
    .replace(/["<>\\\r\n\t]+/g, '')
    .trim().slice(0, 60) || 'MY AI Agent';
}
async function sendEmail(to,subject,html,opts){
  if(!RESEND_KEY){console.log(`[DEV EMAIL] To:${to}\nSubject:${subject}\n${html.replace(/<[^>]+>/g,'')}\n`);return;}
  const displayName = _safeFromName(opts && opts.fromName);
  // CRITICAL: httpsReq does NOT throw on 4xx/5xx — it just resolves with
  // {s, d}. Without this check, Resend errors (422 Domain not verified,
  // 401 Invalid key, 403 Suppressed recipient) get silently swallowed and
  // the AI tells the user "✅ 送信完了" while nothing actually went out.
  const r = await httpsReq('POST','api.resend.com','/emails',
    {'Content-Type':'application/json','Authorization':`Bearer ${RESEND_KEY}`},
    {from:`${displayName} <${FROM_EMAIL}>`,to,subject,html});
  if(r.s >= 200 && r.s < 300){
    console.log(`[email ok] to=${to} subject="${subject.slice(0,40)}" resend_id=${(r.d && r.d.id)||'?'}`);
    return r.d;
  }
  // Surface the actual Resend error so the caller can show it to the user.
  const detail = (r.d && (r.d.message || r.d.error || r.d.name)) || `HTTP ${r.s}`;
  console.error(`[email FAIL] to=${to} status=${r.s} detail=${JSON.stringify(r.d).slice(0,300)}`);
  throw new Error(`Resend ${r.s}: ${detail}`);
}

