// ── AEO / AI 検索モニター ツール (= 自社内蔵ツール) ──
// ChatGPT / Perplexity / Claude / Gemini に query を投げて自社引用を tracking。
// V1 は Perplexity のみ (= login 不要、 citation explicit で抽出しやすい)。
// ══════════════════════════════════════════════════════════════
const AEO_TOOLS = [
  {
    name: 'ai_search_monitor',
    description: 'AI 検索エンジン (Perplexity / ChatGPT / Gemini) に query を投げて、 自社サイトが回答に引用されているかチェック。AEO 部門の主力ツール。 query 例: 「Best SaaS for X」 「○○ おすすめ」 など、 実際にユーザーが AI に聞きそうな質問。\n\nplatform 推奨: 引用が明示的な Perplexity が最も精度高い。 ChatGPT / Gemini はユーザーがログイン済みのブラウザが必要。',
    input_schema: {
      type: 'object',
      properties: {
        query: { type: 'string', description: '検索クエリ (1-200 字)' },
        platform: { type: 'string', enum: ['perplexity','chatgpt','gemini'], description: 'default: perplexity' },
        site_url: { type: 'string', description: '(任意) 自社サイト URL — マッチ判定に使う' },
      },
      required: ['query'],
    },
  },
];
const AEO_TOOL_NAMES = new Set(AEO_TOOLS.map(t => t.name));

// 共通 URL 抽出 + 自社ドメイン除外
function _extractUrlsFromText(text, excludeDomains){
  const pattern = /https?:\/\/[^\s)<>"'\]]+/g;
  const all = (text.match(pattern) || []).filter(u => !excludeDomains.some(d => u.includes(d)));
  return Array.from(new Set(all)).slice(0, 30);
}

// Perplexity に query → answer + citations を抽出
// 改善: streaming 完了を 「Sources」 / 「ソース」 出現で検知 (= 固定 10s sleep より速い + 確実)
async function _queryPerplexity(user, query){
  const url = 'https://www.perplexity.ai/search?q=' + encodeURIComponent(query);
  let r = await executeExtensionTool(user, 'ext_open_url', { url });
  if(r && r.error) return { error: 'open_failed', detail: r.error };

  // Sources セクション出現で streaming 完了と判定 (timeout 20s)
  await executeExtensionTool(user, 'ext_wait_for', {
    text: 'Sources',
    timeout_ms: 20000,
  });
  await _sleep(1500);  // citations のレンダリング完了を待つ buffer

  r = await executeExtensionTool(user, 'ext_read_page', {});
  if(r && r.error) return { error: 'read_failed', detail: r.error };

  const pageText = String((r && r.text) || '');
  // 「Sources」 または 「ソース」 (日本語 UI 用) でセクション分割
  const sourcesIdx = (() => {
    const a = pageText.indexOf('Sources');
    const b = pageText.indexOf('ソース');
    if(a > 100 && b > 100) return Math.min(a, b);
    return a > 100 ? a : (b > 100 ? b : -1);
  })();
  const answerText = (sourcesIdx > 0 ? pageText.slice(0, sourcesIdx) : pageText).slice(0, 2000);

  return {
    ok: true, platform: 'perplexity',
    query,
    perplexity_url: String((r && r.url) || ''),
    answer_excerpt: answerText.trim(),
    cited_urls: _extractUrlsFromText(pageText, ['perplexity.ai']),
    fetched_at: new Date().toISOString(),
  };
}

// ChatGPT に query → 回答抽出 (= 拡張で chatgpt.com を操作、 ユーザーログイン必要)
// 改善: streaming 完了を 「Stop generating」 button 消失で検知
async function _queryChatGPT(user, query){
  // ?q= URL でクエリ事前入力 → submit 自動 or 手動 fallback
  const url = 'https://chatgpt.com/?q=' + encodeURIComponent(query);
  let r = await executeExtensionTool(user, 'ext_open_url', { url });
  if(r && r.error) return { error: 'open_failed', detail: r.error };

  // composer (= 入力欄) 出現を待つ
  await executeExtensionTool(user, 'ext_wait_for', {
    selector: '#prompt-textarea, [contenteditable="true"][id="prompt-textarea"], textarea[placeholder*="Message" i]',
    timeout_ms: 12000,
  });

  // 念のため textarea を確認 → URL の ?q= で auto-fill されてなければ手動入力
  r = await executeExtensionTool(user, 'ext_read_page', {});
  const pageInfo = r || {};
  const currentUrl = String(pageInfo.url || '');
  if(/\/auth\/login|\/login|chatgpt\.com\/auth\//i.test(currentUrl)){
    return { error: 'not_logged_in', detail: 'ChatGPT にログインしてください (chatgpt.com)。' };
  }

  // ?q= で 自動 submit されてなければ手動で type + Enter
  const alreadyAsked = pageInfo.text && pageInfo.text.indexOf(query) >= 0;
  if(!alreadyAsked){
    // 2026 ChatGPT: #prompt-textarea は contenteditable div
    const SELECTORS = [
      '#prompt-textarea',
      '[contenteditable="true"][id="prompt-textarea"]',
      '[contenteditable="true"][data-virtualkeyboard]',
      'textarea[placeholder*="Message" i]',
      'div[contenteditable="true"]',
    ];
    let typed = false;
    for(const sel of SELECTORS){
      r = await executeExtensionTool(user, 'ext_type', { selector: sel, text: query });
      if(!r || !r.error){ typed = true; break; }
    }
    if(!typed) return { error: 'type_failed', detail: 'ChatGPT の入力欄が見つかりません: ' + (r && r.error) };
    await _sleep(800);
    // Send button or Enter
    r = await executeExtensionTool(user, 'ext_click', { target: '[data-testid="send-button"]' });
    if(r && r.error){
      r = await executeExtensionTool(user, 'ext_press_key', { key: 'Enter' });
      if(r && r.error) return { error: 'submit_failed', detail: r.error };
    }
  }

  // Streaming 完了検知: 「Stop generating」 button が消えるまで poll
  // Stop button が存在する間は streaming 中、 消えたら完了
  await _sleep(3000);  // 最低 streaming 開始を待つ
  await _waitForStreamingDone(user, '[data-testid="stop-button"], [aria-label*="Stop generating"], [aria-label*="生成を停止"]', 30000);

  r = await executeExtensionTool(user, 'ext_read_page', {});
  if(r && r.error) return { error: 'read_failed', detail: r.error };
  const pageText = String((r && r.text) || '');

  return {
    ok: true, platform: 'chatgpt',
    query,
    chatgpt_url: String((r && r.url) || ''),
    answer_excerpt: pageText.slice(0, 2000),
    cited_urls: _extractUrlsFromText(pageText, ['chatgpt.com', 'openai.com']),
    fetched_at: new Date().toISOString(),
  };
}

// Streaming 完了検知 helper: 指定 selector の element が消えるまで poll
async function _waitForStreamingDone(user, stopButtonSelector, maxWaitMs){
  const start = Date.now();
  let lastSeen = Date.now();
  while(Date.now() - start < maxWaitMs){
    const check = await executeExtensionTool(user, 'ext_eval', {
      code: `return document.querySelector(${JSON.stringify(stopButtonSelector)}) ? 'streaming' : 'done';`,
    });
    if(check && check === 'done'){
      // 念のため 2 秒安定したら終了
      if(Date.now() - lastSeen > 2000) return;
    } else {
      lastSeen = Date.now();
    }
    await _sleep(1500);
  }
}

// Gemini に query → 回答抽出 (= 拡張で gemini.google.com を操作)
// 改善: Quill editor の selector + ストリーミング完了検知
async function _queryGemini(user, query){
  let r = await executeExtensionTool(user, 'ext_open_url', { url: 'https://gemini.google.com/app' });
  if(r && r.error) return { error: 'open_failed', detail: r.error };

  // 入力欄出現を待つ
  await executeExtensionTool(user, 'ext_wait_for', {
    selector: '.ql-editor[contenteditable="true"], [contenteditable="true"][role="textbox"], rich-textarea [contenteditable="true"]',
    timeout_ms: 12000,
  });

  r = await executeExtensionTool(user, 'ext_read_page', {});
  const pageInfo = r || {};
  const currentUrl = String(pageInfo.url || '');
  if(/accounts\.google\.com|\/signin\//i.test(currentUrl)){
    return { error: 'not_logged_in', detail: 'Gemini (Google) にログインしてください: gemini.google.com' };
  }

  // 入力 — selector 3 段 fallback
  const SELECTORS = [
    '.ql-editor[contenteditable="true"]',
    '[contenteditable="true"][role="textbox"]',
    'rich-textarea [contenteditable="true"]',
    '[contenteditable="true"]',
  ];
  let typed = false;
  for(const sel of SELECTORS){
    r = await executeExtensionTool(user, 'ext_type', { selector: sel, text: query });
    if(!r || !r.error){ typed = true; break; }
  }
  if(!typed) return { error: 'type_failed', detail: 'Gemini の入力欄が見つかりません: ' + (r && r.error) };

  await _sleep(800);
  // 送信 button — aria-label 多言語対応 + class fallback
  r = await executeExtensionTool(user, 'ext_click', { target: '[aria-label*="送信"]' });
  if(r && r.error){
    r = await executeExtensionTool(user, 'ext_click', { target: '[aria-label*="Send" i]' });
    if(r && r.error){
      r = await executeExtensionTool(user, 'ext_click', { target: 'button.send-button' });
      if(r && r.error){
        r = await executeExtensionTool(user, 'ext_press_key', { key: 'Enter' });
      }
    }
  }

  // Streaming 完了検知 (= Gemini の停止ボタン or response-loader 消失)
  await _sleep(3000);
  await _waitForStreamingDone(user, '[aria-label*="応答の生成を停止"], [aria-label*="Stop response" i], .response-loading-indicator, .stop-button', 30000);

  r = await executeExtensionTool(user, 'ext_read_page', {});
  if(r && r.error) return { error: 'read_failed', detail: r.error };
  const pageText = String((r && r.text) || '');

  return {
    ok: true, platform: 'gemini',
    query,
    gemini_url: String((r && r.url) || ''),
    answer_excerpt: pageText.slice(0, 2000),
    cited_urls: _extractUrlsFromText(pageText, ['google.com', 'gstatic.com']),
    fetched_at: new Date().toISOString(),
  };
}

async function executeAiSearchMonitorTool(user, input){
  const query = String((input && input.query) || '').trim();
  if(!query) return { error: 'query_required' };
  if(query.length > 200) return { error: 'query_too_long' };
  if(!user.extension_device_token){
    return { error: 'extension_not_paired', detail: 'AI 検索モニターには Chrome 拡張が必要です。' };
  }
  const platform = String((input && input.platform) || 'perplexity').toLowerCase();
  let r;
  if(platform === 'perplexity')     r = await _queryPerplexity(user, query);
  else if(platform === 'chatgpt')   r = await _queryChatGPT(user, query);
  else if(platform === 'gemini')    r = await _queryGemini(user, query);
  else return { error: 'unknown_platform', detail: 'platform は perplexity / chatgpt / gemini のいずれか' };
  if(r && r.error) return r;

  // self_site 判定 (= input.site_url や user.agents の site_url とマッチするか)
  const candidateSites = [];
  if(input && input.site_url) candidateSites.push(String(input.site_url));
  (user.agents || []).forEach(a => { if(a && a.site_url) candidateSites.push(a.site_url); });
  const ownDomains = candidateSites.map(u => {
    try { return new URL(u).hostname.replace(/^www\./, ''); }
    catch(_){ return u.replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0]; }
  }).filter(Boolean);

  const matchedUrls = r.cited_urls.filter(u => {
    return ownDomains.some(d => d && u.toLowerCase().includes(d.toLowerCase()));
  });
  const mentioned = matchedUrls.length > 0;

  return Object.assign(r, {
    own_domains: ownDomains,
    mentioned,
    matched_urls: matchedUrls,
    instructions: mentioned
      ? 'ユーザーに「✅ Perplexity で『' + query + '』 → 自社が引用されました (' + matchedUrls.length + ' 件)」と報告。'
      : 'ユーザーに「❌ Perplexity で『' + query + '』 → 自社は引用されませんでした。 上位 ' + r.cited_urls.length + ' URL が引用されています」 と報告。 改善提案も添える。',
  });
}

// 小さい sleep helper
function _sleep(ms){ return new Promise(r => setTimeout(r, ms)); }

// ── 共通: 拡張に X.com を開く + テキスト入力までの flow ──
async function _xOpenComposeAndType(user, text){
  // 1) X compose URL を開く
  let r = await executeExtensionTool(user, 'ext_open_url', { url: 'https://x.com/compose/post' });
  if(r && r.error) return { error: 'open_failed: ' + r.error };

  // 2) DOM 安定待ち (= modal が表示されるまで)
  await _sleep(2500);

  // 3) textarea にテキスト入力
  // X の compose textarea セレクタ: [data-testid="tweetTextarea_0"]
  r = await executeExtensionTool(user, 'ext_type', {
    selector: '[data-testid="tweetTextarea_0"]',
    text: text,
  });
  if(r && r.error) return { error: 'type_failed: ' + r.error };
  return { ok: true };
}

// ── verify_x_login: X.com を開いて username 取得 ──
async function executeVerifyXLoginTool(user, agent){
  if(!user.extension_device_token){
    return { error: 'extension_not_paired', detail: 'MY AI Agent ブラウザ拡張を先にインストールしてください。' };
  }
  // 1) X.com を開く
  let r = await executeExtensionTool(user, 'ext_open_url', { url: 'https://x.com/home' });
  if(r && r.error) return { ok: false, error: 'open_failed', detail: r.error };

  await _sleep(2000);

  // 2) ext_read_page で現在の URL とページ内容を確認
  r = await executeExtensionTool(user, 'ext_read_page', {});
  if(r && r.error) return { ok: false, error: 'read_failed', detail: r.error };
  const pageInfo = r || {};
  const currentUrl = String(pageInfo.url || '');
  const pageText = String(pageInfo.text || '').slice(0, 2000);

  // 3) ログインしてれば URL は x.com/home のはず
  //    未ログインなら login / i/flow/login にリダイレクト
  if(/\/login|\/i\/flow\/login|^https:\/\/(www\.)?x\.com\/?$/.test(currentUrl) && !currentUrl.includes('/home')){
    return { ok: false, error: 'not_logged_in', detail: 'X にログインしてください。x.com を開いてログインしてから再試行。' };
  }
  // home に到達してれば logged-in 扱い
  // username 抽出: "/i/" を含むホーム URL より、AppTabBar の Profile link を探す
  // ページテキストから "@username" を最大限ヒューリスティックに抽出
  const handleMatch = pageText.match(/@([A-Za-z0-9_]{2,15})/);
  const username = handleMatch ? '@' + handleMatch[1] : null;
  // per-site が望ましいので agent 渡されてたら agent.sns_connections.x に保存
  const conn = {
    connected: true,
    profile: { username: username || '(取得不可)' },
    last_verified_at: new Date().toISOString(),
  };
  if(agent){
    agent.sns_connections = agent.sns_connections || {};
    agent.sns_connections.x = conn;
  } else {
    user.sns_connections = user.sns_connections || {};
    user.sns_connections.x = conn;
  }
  try { await DB.save(user); } catch(_){}
  return {
    ok: true,
    platform: 'x',
    profile: { username },
    instructions: 'ユーザーに「✅ X (' + (username || 'logged-in') + ') に接続できました」と伝えてください。',
  };
}

// ── post_to_x: 単独 Tweet 投稿 ──
async function executePostToXTool(user, input, agent){
  const text = String((input && input.text) || '').trim();
  if(!text) return { error: 'text_required' };
  if(text.length > 280) return { error: 'too_long', detail: 'X は 280 字まで。今: ' + text.length + ' 字' };
  if(!user.extension_device_token){
    return { error: 'extension_not_paired', detail: 'MY AI Agent ブラウザ拡張を先にインストールしてください。' };
  }

  // 1) compose 開いてテキスト入力
  let r = await _xOpenComposeAndType(user, text);
  if(r && r.error) return r;

  // 2) 投稿ボタンをクリック
  // セレクタ: [data-testid="tweetButton"] / "Post" テキスト
  r = await executeExtensionTool(user, 'ext_click', { target: '[data-testid="tweetButton"]' });
  if(r && r.error){
    // フォールバック: テキスト で探す
    r = await executeExtensionTool(user, 'ext_click', { target: 'Post' });
    if(r && r.error) return { error: 'post_click_failed', detail: r.error };
  }

  // 3) 投稿完了待ち (= toast or URL 変化)
  await _sleep(3000);

  // 4) URL 取得 (= compose 後、Tweet 詳細 URL に redirect されるはず)
  r = await executeExtensionTool(user, 'ext_read_page', {});
  const tweetUrl = (r && r.url) || '';

  return {
    ok: true,
    platform: 'x',
    url: tweetUrl,
    posted_text: text,
    instructions: 'ユーザーに「✅ X に投稿しました ' + (tweetUrl ? '→ ' + tweetUrl : '') + '」と短く報告してください。',
  };
}

// ── post_to_x_thread: スレッド連投 ──
// X の compose modal では「+」 button (= 次の Tweet を追加) を使って 1 つの
// 「post スレッド」として送れる。各 Tweet textarea のセレクタは index で変わる:
//   [data-testid="tweetTextarea_0"], _1, _2, ...
async function executePostToXThreadTool(user, input, agent){
  const tweets = Array.isArray(input && input.tweets) ? input.tweets.map(t => String(t || '').trim()).filter(Boolean) : [];
  if(tweets.length < 2) return { error: 'need_at_least_2' };
  if(tweets.length > 25) return { error: 'too_many', detail: '最大 25 連投' };
  for(let i = 0; i < tweets.length; i++){
    if(tweets[i].length > 280) return { error: 'tweet_too_long', detail: '#' + (i+1) + ' が 280 字超過 (' + tweets[i].length + ' 字)' };
  }
  if(!user.extension_device_token){
    return { error: 'extension_not_paired', detail: 'MY AI Agent ブラウザ拡張を先にインストールしてください。' };
  }

  // 1) compose を開いて 1 個目を入力
  let r = await _xOpenComposeAndType(user, tweets[0]);
  if(r && r.error) return r;

  // 2) Tweet 2 以降: 「+」ボタンを押して新しい textarea を追加 → 入力
  for(let i = 1; i < tweets.length; i++){
    // 「Add post」ボタン: [data-testid="addButton"]
    r = await executeExtensionTool(user, 'ext_click', { target: '[data-testid="addButton"]' });
    if(r && r.error){
      // フォールバック: aria-label で探す
      r = await executeExtensionTool(user, 'ext_click', { target: '[aria-label="Add post"]' });
      if(r && r.error) return { error: 'add_button_failed', detail: 'Tweet ' + (i+1) + ' の追加ボタンが見つからない: ' + r.error };
    }
    await _sleep(800);
    // 新しい textarea に入力 (index は i)
    r = await executeExtensionTool(user, 'ext_type', {
      selector: '[data-testid="tweetTextarea_' + i + '"]',
      text: tweets[i],
    });
    if(r && r.error) return { error: 'type_failed', detail: 'Tweet ' + (i+1) + ': ' + r.error };
  }

  // 3) "Post all" ボタンをクリック
  r = await executeExtensionTool(user, 'ext_click', { target: '[data-testid="tweetButton"]' });
  if(r && r.error){
    r = await executeExtensionTool(user, 'ext_click', { target: 'Post all' });
    if(r && r.error) return { error: 'post_click_failed', detail: r.error };
  }

  await _sleep(4000);

  // 4) URL 取得
  r = await executeExtensionTool(user, 'ext_read_page', {});
  const threadUrl = (r && r.url) || '';

  return {
    ok: true,
    platform: 'x',
    url: threadUrl,
    tweet_count: tweets.length,
    instructions: 'ユーザーに「✅ X に ' + tweets.length + ' 連投スレッドを投稿しました ' + (threadUrl ? '→ ' + threadUrl : '') + '」と短く報告してください。',
  };
}

// ── 各 platform の URL パターン定義 (= URL paste 接続の中核) ──
// 各 entry: { regex, build_url(handle), build_profile(handle) } の 3 つ。
// regex は URL から識別子 (handle / id / shop name 等) を 1 group で抽出。
const SNS_PLATFORM_DEFS = {
  x: {
    regex: /(?:https?:\/\/)?(?:www\.)?(?:x|twitter)\.com\/([A-Za-z0-9_]{1,15})/i,
    handle_only: /^@?([A-Za-z0-9_]{1,15})$/,
    build: h => ({ username: '@' + h, url: 'https://x.com/' + h }),
  },
  linkedin: {
    regex: /(?:https?:\/\/)?(?:www\.)?linkedin\.com\/(?:in|company)\/([A-Za-z0-9_-]+)/i,
    handle_only: /^@?([A-Za-z0-9_-]{2,100})$/,
    build: h => ({ username: '@' + h, url: 'https://www.linkedin.com/in/' + h }),
  },
  threads: {
    regex: /(?:https?:\/\/)?(?:www\.)?threads\.(?:com|net)\/@?([A-Za-z0-9_.]+)/i,
    handle_only: /^@?([A-Za-z0-9_.]{1,30})$/,
    build: h => ({ username: '@' + h, url: 'https://www.threads.com/@' + h }),
  },
  instagram: {
    regex: /(?:https?:\/\/)?(?:www\.)?instagram\.com\/([A-Za-z0-9_.]+)/i,
    handle_only: /^@?([A-Za-z0-9_.]{1,30})$/,
    build: h => ({ username: '@' + h, url: 'https://www.instagram.com/' + h }),
  },
  facebook: {
    regex: /(?:https?:\/\/)?(?:www\.)?facebook\.com\/([A-Za-z0-9._-]+)/i,
    handle_only: /^@?([A-Za-z0-9._-]{2,100})$/,
    build: h => ({ page_id: h, page_name: h, url: 'https://www.facebook.com/' + h }),
  },
  tiktok: {
    regex: /(?:https?:\/\/)?(?:www\.)?tiktok\.com\/@([A-Za-z0-9_.]+)/i,
    handle_only: /^@?([A-Za-z0-9_.]{1,30})$/,
    build: h => ({ username: '@' + h, url: 'https://www.tiktok.com/@' + h }),
  },
  youtube: {
    // @handle 形式 or channel/UC... 形式
    regex: /(?:https?:\/\/)?(?:www\.)?youtube\.com\/(?:@|channel\/)([A-Za-z0-9_-]+)/i,
    handle_only: /^@?([A-Za-z0-9_-]{2,100})$/,
    build: h => ({ channel_id: h, channel_name: h, url: 'https://www.youtube.com/' + (h.startsWith('UC') ? 'channel/' : '@') + h }),
  },
  note: {
    regex: /(?:https?:\/\/)?(?:www\.)?note\.com\/([A-Za-z0-9_]+)/i,
    handle_only: /^@?([A-Za-z0-9_]{2,30})$/,
    build: h => ({ username: h, url: 'https://note.com/' + h }),
  },
  wordpress: {
    // WordPress: site URL 自体 (= yoursite.com or yoursite.com/wp-admin)
    regex: /(?:https?:\/\/)?([a-zA-Z0-9.-]+\.[a-zA-Z]{2,})(?:\/wp-admin)?/i,
    handle_only: null,
    build: domain => ({
      site_name: domain,
      url: 'https://' + domain,
      site_url: 'https://' + domain,
      admin_url: 'https://' + domain + '/wp-admin',
    }),
  },
  shopify: {
    // myshop.myshopify.com 形式 or admin URL
    regex: /(?:https?:\/\/)?([a-z0-9-]+)\.myshopify\.com/i,
    handle_only: /^([a-z0-9-]{2,60})$/,
    build: shop => ({
      shop_name: shop,
      shop_domain: shop + '.myshopify.com',
      url: 'https://' + shop + '.myshopify.com',
      admin_url: 'https://' + shop + '.myshopify.com/admin',
    }),
  },
  base: {
    // admin.thebase.in (BASE Store の admin) or shop.thebase.in (= 公開ショップ)
    // 「admin」 はあなたのショップを示さないので、その場合は shop_name = null
    regex: /(?:https?:\/\/)?(admin|[a-z0-9-]+)\.thebase\.in/i,
    handle_only: /^([a-z0-9-]{2,60})$/,
    build: shop => {
      const isAdmin = shop === 'admin';
      return {
        shop_name: isAdmin ? 'BASE Store' : shop,
        url: isAdmin ? 'https://admin.thebase.in/' : 'https://' + shop + '.thebase.in/',
        admin_url: 'https://admin.thebase.in/',
      };
    },
  },
  emdash: {
    // Cloudflare EmDash — 2026 リリースの AI-native CMS (WordPress 後継)。
    // Deploy 先は Workers / Pages / Netlify / Vercel どれでも可、 ユーザーは
    // サブドメイン or カスタムドメインで運用。 URL paste で接続。
    // 公開 URL or admin URL のどちらでも受け付ける。
    regex: /(?:https?:\/\/)?([a-zA-Z0-9.-]+\.[a-zA-Z]{2,})(?:\/admin)?/i,
    handle_only: null,
    build: domain => ({
      site_name: domain,
      url: 'https://' + domain,
      site_url: 'https://' + domain,
      admin_url: 'https://' + domain + '/admin',
      cms: 'emdash',
    }),
  },
};

// 2026-05-24 per-site connections: agent.sns_connections.<platform> を最優先、
// fallback で user.sns_connections.<platform>。 publish tool 内で全部これ経由に。
function _snsConn(user, agent, platform){
  if(agent && agent.sns_connections && agent.sns_connections[platform]){
    return agent.sns_connections[platform];
  }
  return (user && user.sns_connections && user.sns_connections[platform]) || null;
}

// raw (= URL or handle) から profile を抽出する共通 helper
function _snsExtractProfile(platform, body){
  const def = SNS_PLATFORM_DEFS[platform];
  if(!def) return { error: 'unknown_platform' };
  const raw = String((body && (body.url || body.handle)) || '').trim();
  if(!raw) return { error: 'url_or_handle_required' };
  let h = null;
  const m1 = raw.match(def.regex);
  if(m1) h = m1[1] || m1[2];  // YouTube に group 2 がある場合に備える
  else if(def.handle_only){
    const m2 = raw.match(def.handle_only);
    if(m2) h = m2[1];
  }
  if(!h) return { error: 'invalid_format', detail: platform + ' の URL or handle 形式が不正です' };
  return { profile: def.build(h) };
}

