async function driveListFolders(user, opts){
  const token = await getValidGoogleAccessToken(user);
  const q = encodeURIComponent("mimeType='application/vnd.google-apps.folder' and trashed=false");
  const r = await httpsReq('GET', 'www.googleapis.com',
    '/drive/v3/files?q='+q+'&pageSize=100&fields=files(id,name,modifiedTime,parents)',
    { 'Authorization':'Bearer '+token }, null);
  if(r.s !== 200) throw new Error('Drive list failed: '+JSON.stringify(r.d).slice(0,200));
  return (r.d && r.d.files) || [];
}
async function driveSearchFiles(user, folderId, query){
  const token = await getValidGoogleAccessToken(user);
  const parts = [];
  if(folderId) parts.push(`'${folderId}' in parents`);
  if(query) parts.push(`name contains '${String(query).replace(/'/g, "\\'")}'`);
  parts.push('trashed=false');
  const q = encodeURIComponent(parts.join(' and '));
  const r = await httpsReq('GET', 'www.googleapis.com',
    '/drive/v3/files?q='+q+'&pageSize=50&fields=files(id,name,mimeType,modifiedTime,webViewLink,size)',
    { 'Authorization':'Bearer '+token }, null);
  if(r.s !== 200) throw new Error('Drive search failed: '+JSON.stringify(r.d).slice(0,200));
  return (r.d && r.d.files) || [];
}

// ── GOOGLE WORKSPACE OAUTH (account-linking, 6-in-1) ────────────
// Single OAuth flow that requests scopes for all 6 Google services in the
// integrations catalog: Gmail / Calendar / Drive / GA4 / YouTube / Search
// Console. Reuses GOOGLE_CLIENT_ID/SECRET (already set on Render for login),
// so kota only needs to add the new callback URL to the OAuth client.
const GOOGLE_INTG_SCOPES = [
  'openid', 'email', 'profile',
  'https://www.googleapis.com/auth/gmail.modify',          // Gmail: read, send, drafts, labels
  'https://www.googleapis.com/auth/calendar',              // Calendar: full
  'https://www.googleapis.com/auth/drive',                 // Drive: full
  'https://www.googleapis.com/auth/spreadsheets',          // Sheets (mirrors existing google_oauth)
  'https://www.googleapis.com/auth/analytics.readonly',    // GA4
  'https://www.googleapis.com/auth/youtube',               // YouTube: full
  'https://www.googleapis.com/auth/webmasters.readonly',   // Search Console
].join(' ');
function googleIntgAuthURL(stateJwt){
  const params = new URLSearchParams({
    client_id: GOOGLE_ID,
    redirect_uri: `${APP_URL}/api/auth/google-intg/callback`,
    response_type: 'code',
    scope: GOOGLE_INTG_SCOPES,
    access_type: 'offline',     // request refresh_token
    prompt: 'consent',          // force re-consent so refresh_token comes back even on re-link
    state: stateJwt,
    include_granted_scopes: 'true',
  });
  return `https://accounts.google.com/o/oauth2/v2/auth?${params}`;
}
async function googleIntgExchangeCode(code){
  const r = await httpsReq('POST', 'oauth2.googleapis.com', '/token',
    { 'Content-Type':'application/x-www-form-urlencoded' },
    new URLSearchParams({
      code,
      client_id: GOOGLE_ID,
      client_secret: GOOGLE_SEC,
      redirect_uri: `${APP_URL}/api/auth/google-intg/callback`,
      grant_type: 'authorization_code',
    }).toString());
  if(r.s !== 200) throw new Error('Google integration token exchange failed: ' + JSON.stringify(r.d).slice(0,200));
  return r.d; // { access_token, refresh_token, expires_in, scope, ... }
}
async function googleIntgFetchUser(accessToken){
  const r = await httpsReq('GET', 'www.googleapis.com', '/oauth2/v2/userinfo',
    { 'Authorization':'Bearer '+accessToken }, null);
  if(r.s !== 200) throw new Error('Google userinfo failed');
  return r.d;
}

// ── GITHUB OAUTH (account-linking, not signup) ──────────────────
// Used by the integrations catalog GitHub card. The state token is a short-
// lived JWT carrying the caller's userId so the callback knows whose account
// to attach the GitHub token to. CSRF-safe because only signed states pass.
const GITHUB_OAUTH_SCOPES = 'repo user:email read:org';
function githubAuthURL(stateJwt, returnTo){
  const params=new URLSearchParams({
    client_id: GITHUB_OAUTH_ID,
    redirect_uri: `${APP_URL}/api/auth/github/callback`,
    scope: GITHUB_OAUTH_SCOPES,
    state: stateJwt,
    // Don't force a specific account — let users pick if they have multiple.
    allow_signup: 'false',
  });
  return `https://github.com/login/oauth/authorize?${params}`;
}
async function githubExchangeCode(code){
  const body = new URLSearchParams({
    client_id: GITHUB_OAUTH_ID,
    client_secret: GITHUB_OAUTH_SEC,
    code,
    redirect_uri: `${APP_URL}/api/auth/github/callback`,
  }).toString();
  // GitHub's token endpoint returns form-encoded by default; we ask for JSON.
  const r = await httpsReq('POST', 'github.com', '/login/oauth/access_token',
    { 'Content-Type':'application/x-www-form-urlencoded', 'Accept':'application/json', 'User-Agent':'MY-AI-Agent' },
    body);
  if(r.s !== 200) throw new Error('GitHub token exchange failed: ' + JSON.stringify(r.d).slice(0,200));
  if(r.d && r.d.error) throw new Error('GitHub OAuth error: ' + (r.d.error_description || r.d.error));
  return r.d; // { access_token, scope, token_type }
}
async function githubFetchUser(accessToken){
  const r = await httpsReq('GET', 'api.github.com', '/user',
    { 'Authorization':'Bearer '+accessToken, 'Accept':'application/vnd.github+json', 'User-Agent':'MY-AI-Agent' }, null);
  if(r.s !== 200) throw new Error('GitHub /user failed: ' + r.s);
  return r.d;
}

// ── X (Twitter) OAUTH 2.0 with PKCE ──────────────────────────
// Confidential client flow. PKCE adds a code_verifier (random 64-char)
// that's regenerated on each /start and required at code-exchange time.
// We embed the verifier in the (signed) state JWT — short-lived (10 min)
// and only reachable via HTTPS, acceptable for this server-side flow.
const X_OAUTH_SCOPES = 'tweet.read tweet.write users.read offline.access';
function _xGenVerifier(){
  // base64url(32 random bytes) → ~43 chars, well within PKCE spec 43-128.
  return crypto.randomBytes(32).toString('base64')
    .replace(/=/g,'').replace(/\+/g,'-').replace(/\//g,'_');
}
function _xVerifierToChallenge(verifier){
  return crypto.createHash('sha256').update(verifier).digest('base64')
    .replace(/=/g,'').replace(/\+/g,'-').replace(/\//g,'_');
}
function xAuthURL(stateJwt, codeChallenge){
  const params = new URLSearchParams({
    response_type: 'code',
    client_id: X_OAUTH_ID,
    redirect_uri: `${APP_URL}/api/auth/x/callback`,
    scope: X_OAUTH_SCOPES,
    state: stateJwt,
    code_challenge: codeChallenge,
    code_challenge_method: 'S256',
  });
  // X currently serves the OAuth UI at https://x.com (and twitter.com still works).
  return `https://x.com/i/oauth2/authorize?${params}`;
}
async function xExchangeCode(code, codeVerifier){
  // Confidential client → HTTP Basic with client_id:client_secret
  const basic = Buffer.from(X_OAUTH_ID+':'+X_OAUTH_SEC).toString('base64');
  const body = new URLSearchParams({
    code,
    grant_type: 'authorization_code',
    client_id: X_OAUTH_ID,  // required even with Basic auth for X
    redirect_uri: `${APP_URL}/api/auth/x/callback`,
    code_verifier: codeVerifier,
  }).toString();
  const r = await httpsReq('POST', 'api.x.com', '/2/oauth2/token',
    { 'Content-Type':'application/x-www-form-urlencoded', 'Authorization':'Basic '+basic },
    body);
  if(r.s !== 200) throw new Error('X token exchange failed: ' + JSON.stringify(r.d).slice(0,200));
  if(r.d && r.d.error) throw new Error('X OAuth error: ' + (r.d.error_description || r.d.error));
  return r.d; // { access_token, refresh_token, token_type, expires_in, scope }
}
async function xFetchUser(accessToken){
  const r = await httpsReq('GET', 'api.x.com', '/2/users/me?user.fields=username,name,profile_image_url',
    { 'Authorization':'Bearer '+accessToken }, null);
  if(r.s !== 200) throw new Error('X /users/me failed: ' + r.s);
  return r.d && r.d.data ? r.d.data : r.d;
}

