function _scheduleNextRun(s, fromMs){
  // All math in UTC. tz_offset_min is the user's UTC offset (e.g. +540 for JST).
  // The user wants "9am in their local time" so we compute that as
  // (UTC_hour - tz_offset/60) modulo 24.
  const now = fromMs ? new Date(fromMs) : new Date();
  const tz = Number(s.tz_offset_min || 0);
  if(s.kind === 'hourly'){
    // Fire every hour at the configured minute.
    const next = new Date(now);
    next.setUTCSeconds(0,0);
    const minute = Math.max(0, Math.min(59, Number(s.minute||0)));
    next.setUTCMinutes(minute);
    if(next.getTime() <= now.getTime()){
      next.setTime(next.getTime() + 60*60*1000);
    }
    return next.toISOString();
  }
  if(s.kind === 'daily'){
    // Target HH:MM in the user's local timezone — that's
    // (HH - tz/60) mod 24 in UTC, with day rollover.
    const hourLocal = Math.max(0, Math.min(23, Number(s.hour||9)));
    const minuteLocal = Math.max(0, Math.min(59, Number(s.minute||0)));
    // Compute today's target (UTC). Convert "local HH:MM" → UTC.
    const utc = new Date(Date.UTC(
      now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate(),
      hourLocal, minuteLocal, 0, 0
    ));
    utc.setTime(utc.getTime() - tz * 60 * 1000);
    if(utc.getTime() <= now.getTime()){
      utc.setTime(utc.getTime() + 24*60*60*1000);
    }
    return utc.toISOString();
  }
  // Default: 1 hour from now.
  return new Date(now.getTime() + 60*60*1000).toISOString();
}
async function _runOneSchedule(user, agent, sched){
  // Execute the schedule's prompt as if the user sent it, WITH the same tool
  // suite the live chat has (minus Chrome/Playwright — too heavy to spin up
  // every minute). Without tools, prompts like "GA4データを取得→メール送信"
  // would hallucinate <tool_call> XML into the reply (the bug we're fixing).
  //
  // Caps:
  //   MAX_ITERS = 10   — scheduled tasks shouldn't chain endlessly
  //   BUDGET_MS = 90s  — Render scheduler tick is 60s, give some headroom
  //
  // Double-send guard: if the AI calls send_email itself, skip the deliver=email
  // wrap-up so the user doesn't get the same report twice.
  try {
    const promptStr = String(sched.prompt || '');
    // Build the same tool catalog as the chat handler, modulo browser.
    const sheetsActive = !!(agent.sheets_enabled && user.google_tokens);
    const githubActive = !!(agent.github_enabled && user && (user.github_pat || (user.integrations && user.integrations.github && user.integrations.github.pat)));
    const _mediaTools = MEDIA_UTIL_TOOLS.map(t => {
      if(t.name !== 'send_email') return t;
      const ownerEmail = (user && user.email) || '';
      if(!ownerEmail) return t;
      return { ...t,
        description: 'メールを ' + ownerEmail + ' (この AI を呼んだユーザー本人のメールアドレス) に送信します。'
          + '宛先は ' + ownerEmail + ' に固定されているので「メールアドレスを教えて」と聞く必要はありません。'
          + '要約・レポート・リマインダー・調査結果の自分宛通知に使ってください。他人への送信は不可。',
      };
    });
    const _mcpCompose = await _composeMcpToolsForAgent(user, agent);
    const _mcpRouting = _mcpCompose.routing;
    const _allTools = [
      ...IMAGE_TOOLS,
      ...VIDEO_TOOLS,
      ..._mediaTools,
      ...WEB_NATIVE_TOOLS,
      ...(sheetsActive ? SHEETS_TOOLS : []),
      ...(githubActive ? GITHUB_TOOLS : []),
      ..._mcpCompose.tools,
    ];
    // Intent-based filtering reuses the chat handler's logic.
    const intentCategories = _detectIntentCategories(promptStr);
    const tools = _filterToolsByIntent(_allTools, new Set(intentCategories));

    const sys = buildSystem(agent, {
      memories: (user.memories || []),
      kbHits: _retrieveKbChunks(agent, promptStr, 3),
      userQuery: promptStr,
      opUser: user,
      intentCategories,
      sheetsActive,
      recentHistory: (agent.history||[]).slice(-6),
    });

    const sheetsToolNames = new Set(SHEETS_TOOLS.map(t => t.name));
    let convMsgs = [...(agent.history||[]), { role:'user', content: promptStr }];
    let totalIn = 0, totalOut = 0;
    let finalReply = '';
    const toolLog = [];
    let sendEmailCalled = false;     // double-send guard
    const startedAt = Date.now();
    const MAX_ITERS = 10;
    const BUDGET_MS = 90 * 1000;

    for(let iter = 0; iter < MAX_ITERS; iter++){
      if(Date.now() - startedAt > BUDGET_MS){
        console.warn('[schedule] budget exhausted on iter', iter, 'sched=', sched.id);
        break;
      }
      _trimToolHistory(convMsgs);
      const resp = await callAIWithTools(convMsgs, sys, tools, null, agent.model, agent);
      totalIn  += (resp.usage?.input_tokens)  || 0;
      totalOut += (resp.usage?.output_tokens) || 0;

      // Text portion of this turn — used as the final reply if no further tools fire.
      const text = (resp.content||[]).filter(b => b.type==='text').map(b => b.text).join('\n').trim();
      if(text) finalReply = text;

      if(resp.stop_reason !== 'tool_use') break;
      convMsgs.push({ role:'assistant', content: resp.content });

      const toolResultBlocks = [];
      for(const block of (resp.content||[])){
        if(block.type !== 'tool_use') continue;
        let result;
        try {
          if(block.name === 'generate_image')      result = await executeImageTool(block.name, block.input||{});
          else if(block.name === 'edit_image')     result = await executeImageEditTool(block.input||{});
          else if(block.name === 'generate_video') result = await executeVideoTool(block.name, block.input||{});
          else if(block.name === 'generate_audio') result = await executeAudioTool(block.input||{});
          else if(block.name === 'generate_pdf')   result = await executePdfTool(block.input||{});
          else if(block.name === 'generate_chart') result = await executeChartTool(block.input||{});
          else if(block.name === 'generate_diagram') result = await executeDiagramTool(block.input||{});
          else if(block.name === 'generate_qr')    result = await executeQrTool(block.input||{});
          else if(block.name === 'send_email'){
            sendEmailCalled = true;
            result = await executeEmailTool(user, agent, block.input||{});
          }
          else if(block.name === 'create_artifact'){ result = await executeArtifactTool(block.input||{}, user, _artifactOriginCtx(agent, null)); if(result&&result.url&&agent){var _afn1=String(result.url).split('/').pop();agent.current_artifact=_afn1;if(!agent.pinned_artifact)agent.pinned_artifact=_afn1;} }
          else if(block.name === 'edit_artifact'){ result = await executeEditArtifactTool(block.input||{}, user, agent && agent.pinned_artifact); if(result&&result.url&&agent)agent.current_artifact=String(result.url).split('/').pop(); }
          else if(block.name === 'read_artifact')   result = await executeReadArtifactTool(block.input||{}, user, agent && agent.pinned_artifact);
          else if(block.name === 'notify_slack')    result = await executeNotifyTool('slack', user, block.input||{}, agent);
          else if(block.name === 'notify_discord')  result = await executeNotifyTool('discord', user, block.input||{}, agent);
          else if(block.name === 'zapier_run')      result = await executeZapierTool(user, block.input||{});
          else if(block.name === 'ga4_list_properties') result = await executeGa4ListPropertiesTool(user);
          else if(block.name === 'ga4_query')           result = await executeGa4QueryTool(user, agent, block.input||{});
          else if(block.name === 'ga4_set_default')     result = await executeGa4SetDefaultTool(user, agent, block.input||{});
          else if(block.name === 'gsc_list_sites')      result = await executeGscListSitesTool(user);
          else if(block.name === 'gsc_query')           result = await executeGscQueryTool(user, agent, block.input||{});
          else if(block.name === 'gsc_set_default')     result = await executeGscSetDefaultTool(user, agent, block.input||{});
          else if(block.name === 'drive_list_folders')  result = await executeDriveListFoldersTool(user);
          else if(block.name === 'drive_search_files')  result = await executeDriveSearchFilesTool(user, agent, block.input||{});
          else if(block.name === 'drive_set_default_folder') result = await executeDriveSetDefaultFolderTool(user, agent, block.input||{});
          else if(block.name === 'wordpress_publish')   result = await executeWordPressPublishTool(user, agent, block.input||{});
          else if(block.name === 'wordpress_test_connection') result = await executeWordPressTestConnectionTool(user, agent, block.input||{});
          else if(block.name === 'share_to_sns')        result = await executeShareToSnsTool(block.input||{});
          else if(block.name === 'buffer_list_profiles') result = await executeBufferListProfilesTool(user);
          else if(block.name === 'buffer_post')          result = await executeBufferPostTool(user, block.input||{});
          else if(block.name === 'generate_agent_promo_video') result = await executeAgentPromoVideo(agent);
          else if(block.name === 'web_screenshot')   result = await executeWebScreenshotTool(block.input||{});
          else if(block.name === 'web_read_markdown') result = await executeWebReadMdTool(block.input||{});
          else if(block.name === 'web_extract')      result = await executeWebExtractTool(block.input||{});
          else if(sheetsToolNames.has(block.name))   result = await executeSheetsTool(user, block.name, block.input||{});
          else if(block.name && block.name.startsWith('github_')) result = await executeGitHubTool(user, block.name, block.input||{});
          else if(block.name && block.name.startsWith('mcp_') && _mcpRouting && _mcpRouting.has(block.name)){
            const route = _mcpRouting.get(block.name);
            result = await _mcpCallTool(route.server, route.toolName, block.input || {});
          }
          else if(block.name && SNS_TOOL_NAMES.has(block.name)) result = await executeSnsTool(user, block.name, block.input||{}, agent);
          else if(block.name && AEO_TOOL_NAMES.has(block.name)) result = await executeAiSearchMonitorTool(user, block.input||{});
          else result = { error: 'tool_unavailable_in_schedule: ' + block.name };
        } catch(toolErr){
          result = { error: (toolErr && toolErr.message) || String(toolErr) };
        }
        toolResultBlocks.push(buildToolResult(block.id, block.name, result));
        toolLog.push({
          name: block.name,
          input: block.input || {},
          ok: !(result && result.error),
          url: result && result.url,
          title: result && result.title,
          error: result && result.error,
        });
      }
      convMsgs.push({ role:'user', content: toolResultBlocks });
    }

    if(!finalReply) finalReply = '(レポートを生成できませんでした)';
    const cost = calcCost(totalIn, totalOut);
    const ts = new Date().toLocaleTimeString('en-GB', {hour:'2-digit',minute:'2-digit',hour12:false});
    agent.history = [
      ...(agent.history||[]),
      { role:'user', content: promptStr, time: ts, scheduled:true, schedule_id:sched.id },
      { role:'assistant', content: finalReply, time: ts, cost_jpy: cost.jpy, scheduled:true,
        tool_log: toolLog.length ? toolLog : undefined },
    ];
    if(agent.history.length > 500) agent.history = agent.history.slice(-500);
    user.balance_jpy = Math.round(((user.balance_jpy||0) - cost.jpy) * 1000) / 1000;

    // Auto-deliver email — skip if the AI already called send_email itself
    // (otherwise the user gets two emails — one with the report + one with the
    // raw text). `wrap-up` email is for routines where the AI just generates
    // text and we email it on the AI's behalf.
    if(sched.deliver === 'email' && user.email && !sendEmailCalled){
      const isJa = /[ぁ-んァ-ヶー一-龠]/.test((user.name||'') + (user.email||''));
      const isMorningReport = /毎朝レポート|morning.?report/i.test(sched.label || '');
      try {
        if(isMorningReport){
          // ── リッチ HTML テンプレ (= 朝の briefing 専用) ─────────────
          await sendEmail(
            user.email,
            _buildMorningReportSubject(agent, isJa),
            _buildMorningReportHTML(user, agent, finalReply, sched, isJa)
          );
        } else {
          // ── 既存テンプレ (= 一般的な定期実行レポート) ────────────
          const subj = isJa
            ? `🤖 ${sched.label || agent.name || 'AI'} — 定期実行レポート`
            : `🤖 ${sched.label || agent.name || 'AI'} — scheduled report`;
          const tagline   = isJa ? '定期タスクからの自動実行' : 'Triggered by your scheduled task';
          const promptLbl = isJa ? 'プロンプト:'           : 'Prompt:';
          const noLabel   = isJa ? '(ラベルなし)'           : '(no label)';
          await sendEmail(
            user.email, subj,
            '<div style="font-family:system-ui;max-width:600px;margin:0 auto;padding:20px">'+
            '<h2 style="margin:0 0 8px">'+_xmlEscape(agent.name||'AI')+'</h2>'+
            '<div style="color:#52525b;font-size:13px;margin-bottom:14px">'+tagline+': <i>'+_xmlEscape(sched.label||noLabel)+'</i></div>'+
            '<div style="font-size:11px;color:#a1a1aa;margin-bottom:6px"><b>'+promptLbl+'</b> '+_xmlEscape(sched.prompt||'')+'</div>'+
            '<div style="background:#fff7ed;border:1px solid #f5e1cd;padding:14px;border-radius:10px;white-space:pre-wrap;font-size:14px;line-height:1.55">'+_xmlEscape(finalReply)+'</div>'+
            '<div style="margin-top:18px;text-align:center;color:#a1a1aa;font-size:11px">— MY AI AGENT</div>'+
            '</div>'
          );
        }
      } catch(e){ console.warn('[schedule] email failed:', e.message); }
    }
    sched.last_run = new Date().toISOString();
    sched.next_run = _scheduleNextRun(sched);
    sched.last_error = null;
    console.log('[schedule] ran sched=', sched.id, 'iters=', toolLog.length, 'send_email=', sendEmailCalled);
  } catch(e){
    sched.last_error = (e && e.message || String(e)).slice(0, 200);
    console.warn('[schedule] run failed:', sched.id, sched.last_error);
    // Push next_run forward 1h so we don't spin on persistent failures.
    sched.next_run = new Date(Date.now() + 60*60*1000).toISOString();
  }
}
let _scheduleTimer = null;
let _lastInactivityCheck = 0;
// ── Nightly draft generator: 22:00-06:00 JST、 各 site agent に対し 1 記事/夜 を AI が生成 ──
// "AI が深夜に動いて、 朝起きたら成果物が並んでる" の体験を作る。
let _nightlyTimer = null;
function _startNightlyDraftGenerator(){
  if(_nightlyTimer) return;
  // 30 分ごとに JST hour チェック。 22:00-06:00 (JST) なら稼働。
  const TICK_MS = 30 * 60 * 1000;
  _nightlyTimer = setInterval(async () => {
    try {
      const now = new Date();
      const jstMs = now.getTime() + (now.getTimezoneOffset() + 9 * 60) * 60 * 1000;
      const jst = new Date(jstMs);
      const jstHour = jst.getUTCHours();
      // JST 22-23 or 0-5 のみ稼働
      if(jstHour >= 6 && jstHour < 22) return;

      // 「今夜」 のキー = JST で 18:00 切り (深夜 → 朝の連続を 1 夜と扱う)
      const nightDate = jstHour < 18
        ? new Date(jstMs - 24 * 3600 * 1000)
        : jst;
      const nightKey = nightDate.toISOString().slice(0, 10) + '-night';

      const users = USE_SUPA
        ? (await sbReq('GET','users','?select=*&limit=2000')).d || []
        : LDB.all();

      let generatedCount = 0;
      for(const u of users){
        if(!u || !Array.isArray(u.agents)) continue;
        let changed = false;
        for(const ag of u.agents){
          if(!ag || !ag.site_url) continue; // site agent のみ
          if(ag._nightly_run_key === nightKey) continue; // 今夜は既に実行済み

          // ロードマップから未着手タスク (current week 優先) を 1 件取得
          const task = _pickNightlyDraftTask(ag);
          if(!task) {
            ag._nightly_run_key = nightKey; // タスクなしでもキーを set (再度 try しない)
            ag._nightly_skipped = 'no_task';
            changed = true;
            continue;
          }

          // タスクから記事テーマを生成
          const topic = _topicFromTask(task);
          if(!topic) continue;

          // 既に同テーマで生成済みかチェック (重複防止)
          const existing = (u.notes || []).find(n =>
            n && n.agent_id === ag.id && n.type === 'article_draft'
            && (n.title || '').toLowerCase().includes(topic.toLowerCase().slice(0, 20))
          );
          if(existing){
            ag._nightly_run_key = nightKey;
            ag._nightly_skipped = 'duplicate';
            changed = true;
            continue;
          }

          // 生成
          try {
            await _generateNightlyDraft(u, ag, topic);
            ag._nightly_run_key = nightKey;
            ag._nightly_last_at = new Date().toISOString();
            ag._nightly_skipped = null;
            changed = true;
            generatedCount++;
            console.log('[nightly-draft] generated user=' + u.id + ' agent=' + ag.id + ' topic=' + topic.slice(0, 60));
          } catch(e){
            console.warn('[nightly-draft] gen failed user=' + u.id + ' agent=' + ag.id + ':', e.message);
          }

          // 1 user につき 1 agent だけ生成 (rate limit & 公平性)
          break;
        }
        if(changed){
          try { await DB.save(u); }
          catch(e){ console.warn('[nightly-draft] save failed:', e.message); }
        }
        // API rate-limit 考慮で 1 秒スリープ
        if(changed) await new Promise(r => setTimeout(r, 1000));
      }
      if(generatedCount > 0){
        console.log('[nightly-draft] tick complete, generated=' + generatedCount);
      }
    } catch(e){
      console.warn('[nightly-draft] tick failed:', e.message);
    }
  }, TICK_MS);
  console.log('[nightly-draft] generator started (30 min tick, JST 22:00-06:00 active)');
}

// ロードマップから今夜生成する記事用タスクを 1 件 pick
function _pickNightlyDraftTask(ag){
  const rm = ag.roadmap;
  if(!rm || !Array.isArray(rm.weeks)) return null;
  // 現在週 (= ロードマップ生成からの経過週、 max 8)
  const generatedMs = Date.parse(rm.generated_at || 0) || Date.now();
  const weeksElapsed = Math.floor((Date.now() - generatedMs) / (7 * 86400000));
  const curWeek = Math.min(rm.weeks.length, Math.max(1, weeksElapsed + 1));
  // 今週 → 来週 → ... の順で探す
  for(let wIdx = curWeek - 1; wIdx < Math.min(rm.weeks.length, curWeek + 2); wIdx++){
    const w = rm.weeks[wIdx];
    if(!w || !Array.isArray(w.tasks)) continue;
    // 記事関連のタスクを優先 (= "記事", "執筆", "ライティング", "rewrite", "title" 等を含む)
    const articleTask = w.tasks.find(t =>
      t && !t.done && /記事|執筆|ライティング|rewrite|タイトル|H2|内部リンク|コンテンツ|ブログ/i.test(t.text || '')
    );
    if(articleTask) return articleTask;
    // 任意の未完了タスクで fallback
    const anyTask = w.tasks.find(t => t && !t.done);
    if(anyTask) return anyTask;
  }
  return null;
}

// タスク文からテーマ文字列を生成
function _topicFromTask(task){
  if(!task || typeof task.text !== 'string') return null;
  let topic = task.text.trim();
  // 「○○の記事を書く」 → 「○○」 のような変換
  topic = topic.replace(/^[「【\[]/, '').replace(/[」】\]]$/, '');
  topic = topic.replace(/(?:について)?(?:の)?(記事|ブログ)を?(書く|執筆|作る|まとめる).*$/, '');
  topic = topic.replace(/^(?:記事|ブログ)[:：]?\s*/, '');
  if(topic.length < 5) topic = task.text.trim();
  return topic.slice(0, 120);
}

// 1 件の夜間ドラフト生成 (= /artifact/generate-draft endpoint と同じロジック、 直接呼び出し版)
async function _generateNightlyDraft(user, ag, topic){
  // サイトコンテキスト
  let siteContext = '';
  try {
    const preview = await _fetchSitePreview(ag);
    if(preview && preview.content){
      siteContext = '\n【既存サイトの内容 (= トーン参考)】\n' + String(preview.content).slice(0, 1500);
    }
  } catch(e){ /* ignore */ }

  const prompt = `あなたはこのサイトのプロのコンテンツライターです。以下のテーマで記事の下書きを Markdown 形式で書いてください。

【サイト】${ag.site_url || ag.name} (${ag.site_vertical || 'general'})
【記事テーマ】${topic}
【目標字数】2,500 字 (±10% 許容)${siteContext}

【書き方ルール】
- 冒頭に H1 タイトル (検索意図キーワード含む)
- H2 / H3 で適切に章立て (3-5 個の H2)
- 結論を冒頭でわかりやすく
- 具体例・データ・体験談を盛り込む
- SEO に強い構成 (同義語散布、関連語、見出しに KW)
- 最後の段落で読者が「次に何をすべきか」を明示

完成度の高い、 そのまま WordPress に貼れる下書きを出力してください。`;

  const reply = await callAI([{role:'user', content: prompt}], '', 'sonnet', ag);
  if(!reply || reply.length < 400) throw new Error('AI returned empty/short');

  let articleTitle = topic;
  const h1Match = reply.match(/^#\s+(.+)$/m);
  if(h1Match) articleTitle = h1Match[1].trim().slice(0, 200);

  user.notes = Array.isArray(user.notes) ? user.notes : [];
  if(user.notes.length >= 1000) throw new Error('note limit reached');
  const noteId = 'note_' + crypto.randomBytes(5).toString('hex');
  const now = new Date().toISOString();
  user.notes.push({
    id: noteId,
    agent_id: ag.id,
    title: articleTitle,
    content: reply.slice(0, 100000),
    type: 'article_draft',
    auto_generated: true,
    nightly_generated: true,
    created_at: now,
    updated_at: now,
  });
  return { ok: true, note_id: noteId, title: articleTitle };
}

function _startAgentScheduler(){
  if(_scheduleTimer) return;
  _scheduleTimer = setInterval(async () => {
    try {
      const users = USE_SUPA
        ? (await sbReq('GET','users','?select=id,email,name,memories,agents,balance_jpy,plan&limit=2000')).d || []
        : LDB.all();
      const nowMs = Date.now();
      for(const u of users){
        let changed = false;
        for(const ag of (u.agents||[])){
          for(const s of (ag.schedules||[])){
            if(!s.enabled) continue;
            if(!s.next_run){ s.next_run = _scheduleNextRun(s); changed = true; continue; }
            if(new Date(s.next_run).getTime() > nowMs) continue;
            await _runOneSchedule(u, ag, s);
            changed = true;
          }
        }
        if(changed){
          try { await DB.save(u); }
          catch(e){ console.warn('[schedule] save failed:', e.message); }
        }
      }
      // ── 1 時間に 1 回、未利用ユーザー呼び戻しチェック ──
      if(nowMs - _lastInactivityCheck > 3600 * 1000){
        _lastInactivityCheck = nowMs;
        await _checkInactiveUsers(users).catch(e => console.warn('[inactivity] failed:', e.message));
      }
    } catch(e){
      console.warn('[schedule] tick failed:', e.message);
    }
  }, 60 * 1000);
  console.log('[schedule] agent scheduler started (60s tick)');
}

// ── 24h 未利用ユーザーを検知して呼び戻しメール送信 ──
// 条件: site agent 持ち + 作成から 24h 経過 + 一度もチャット履歴に user 発言なし
//       + welcome mail と inactivity mail を未送信 (= 二重送信防止)
async function _checkInactiveUsers(users){
  const nowMs = Date.now();
  const CUTOFF_MIN = 24 * 60 * 60 * 1000;
  const CUTOFF_MAX = 72 * 60 * 60 * 1000;  // 24-72h の人だけ (= 古すぎる人には送らない)
  for(const u of users){
    if(!u || !u.email) continue;
    if(u._inactivity_mail_sent) continue;  // 二重送信防止 flag
    const siteAg = (u.agents || []).find(a => a && a.site_url);
    if(!siteAg) continue;
    const createdMs = Date.parse(siteAg.created_at || 0) || 0;
    if(!createdMs) continue;
    const ageMs = nowMs - createdMs;
    if(ageMs < CUTOFF_MIN || ageMs > CUTOFF_MAX) continue;
    // チャット履歴で user 発言が 1 件もない (= via_kickoff やシステム発言を除く)
    const hasUserChat = (siteAg.history || []).some(m => m && m.role === 'user' && !m.scheduled && !m.via_kickoff);
    if(hasUserChat) continue;
    // 送信
    try {
      await _sendInactivityMail(u, siteAg);
      u._inactivity_mail_sent = new Date().toISOString();
      try { await DB.save(u); } catch(_){}
      console.log('[inactivity-mail] sent to', u.email);
    } catch(e){
      console.warn('[inactivity-mail] send failed for', u.email, ':', e.message);
    }
  }
}

